window.QUIZ_QUESTIONS=Object.freeze([{"id": 1, "subject": "criminal", "question": "Ai sensi dell’art. 299 c.p.p., quando le esigenze cautelari risultano attenuate, il giudice:", "correct": "Sostituisce la misura applicata con un’altra meno grave oppure ne dispone l’applicazione con modalità meno gravose, nei casi previsti dalla legge.", "wrong": ["Può sostituire la misura con una meno grave soltanto se il pubblico ministero presta il proprio consenso.", "Non può modificare la misura cautelare prima della sentenza definitiva."]}, {"id": 2, "subject": "criminal", "question": "Ai sensi dell’art. 61 c.p.p., i diritti e le garanzie riconosciuti all’imputato si estendono anche alla persona sottoposta alle indagini preliminari?", "correct": "Sì, i diritti e le garanzie dell’imputato si estendono anche alla persona sottoposta alle indagini preliminari.", "wrong": ["Sì, ma soltanto dopo la richiesta di rinvio a giudizio da parte del pubblico ministero.", "No, perché durante le indagini preliminari la persona non può avvalersi delle garanzie riconosciute all’imputato."]}, {"id": 3, "subject": "criminal", "question": "Se l’imputato, dopo essere comparso in udienza, si allontana dall’aula, come viene considerato ai fini del processo?", "correct": "È considerato presente ed è rappresentato dal difensore.", "wrong": ["È automaticamente considerato assente e il processo deve essere sospeso.", "È considerato contumace e il processo deve essere rinviato."]}, {"id": 4, "subject": "criminal", "question": "Ai sensi dell’art. 238 c.p.p., quando è ammessa l’acquisizione nel processo penale dei verbali di prove assunte in un giudizio civile?", "correct": "Quando il giudizio civile si è concluso con una sentenza passata in giudicato.", "wrong": ["Quando il giudizio civile è ancora pendente, indipendentemente dalle condizioni previste dalla legge.", "Mai, perché le prove assunte nel processo civile non possono essere utilizzate nel processo penale."]}, {"id": 5, "subject": "criminal", "question": "Quale delle seguenti misure cautelari personali non è una misura interdittiva?", "correct": "L’obbligo di dimora.", "wrong": ["La sospensione dall’esercizio di un pubblico ufficio o servizio.", "La sospensione dall’esercizio della responsabilità genitoriale."]}, {"id": 6, "subject": "criminal", "question": "Ai sensi dell’art. 307 c.p.p., se un imputato viene scarcerato per decorrenza dei termini di custodia cautelare, il giudice può applicare altre misure cautelari?", "correct": "Sì, quando ne ricorrono i presupposti e persistono le ragioni che avevano determinato la custodia cautelare, ferme le disposizioni particolari previste dalla legge.", "wrong": ["No, la scadenza dei termini impedisce in ogni caso l’applicazione di qualsiasi altra misura cautelare.", "Sì, ma soltanto entro dieci giorni dalla scarcerazione."]}, {"id": 7, "subject": "criminal", "question": "Ai sensi dell’art. 591 c.p.p., quale conseguenza comporta la presentazione di un’impugnazione da parte di chi non ha interesse a proporla?", "correct": "L’impugnazione è inammissibile.", "wrong": ["L’impugnazione è nulla, ma può essere sanata mediante ratifica del giudice.", "L’impugnazione è annullabile soltanto su richiesta del pubblico ministero."]}, {"id": 8, "subject": "criminal", "question": "Ai sensi dell’art. 26 c.p.p., l’inosservanza delle norme sulla competenza del giudice comporta l’inefficacia delle prove già acquisite?", "correct": "No, l’inosservanza delle norme sulla competenza non determina, di per sé, l’inefficacia delle prove già acquisite.", "wrong": ["Sì, tutte le prove già acquisite diventano automaticamente inutilizzabili.", "Sì, ma soltanto le prove documentali e le dichiarazioni testimoniali."]}, {"id": 9, "subject": "criminal", "question": "Ai sensi dell’art. 497 c.p.p., il testimone che non ha ancora compiuto quattordici anni presta giuramento prima di essere esaminato?", "correct": "No, non presta giuramento, ma viene avvertito dell’obbligo di dire la verità e delle responsabilità previste dalla legge.", "wrong": ["Sì, presta sempre giuramento secondo la stessa formula prevista per i testimoni maggiorenni.", "Sì, ma soltanto nei procedimenti relativi a reati puniti con l’ergastolo."]}, {"id": 10, "subject": "criminal", "question": "Chi autorizza, di regola, il pubblico ministero a disporre le operazioni di intercettazione delle comunicazioni telefoniche?", "correct": "Il giudice per le indagini preliminari, con decreto motivato, in presenza dei presupposti previsti dalla legge.", "wrong": ["Il giudice del dibattimento, dopo aver valutato le prove già raccolte dal pubblico ministero.", "La Corte d’appello, su richiesta del Procuratore Generale."]}, {"id": 11, "subject": "criminal", "question": "Ai sensi dell’art. 589 c.p.p., è possibile rinunciare a un’impugnazione già proposta?", "correct": "Sì, possono rinunciarvi il pubblico ministero e le parti private che l’hanno proposta, nei modi e nei termini previsti dalla legge.", "wrong": ["Sì, ma soltanto il pubblico ministero può rinunciare all’impugnazione.", "No, una volta proposta l’impugnazione, la rinuncia non è mai ammessa."]}, {"id": 12, "subject": "criminal", "question": "Ai sensi dell’art. 103 c.p.p., sono consentite le intercettazioni delle conversazioni o comunicazioni dei difensori relative all’attività professionale?", "correct": "No, sono vietate, salvo l’eccezione prevista dalla legge per le conversazioni o comunicazioni che costituiscono corpo del reato.", "wrong": ["Sì, purché il pubblico ministero ritenga che possano essere utili alle indagini.", "Sì, purché l’intercettazione sia autorizzata dal presidente del tribunale."]}, {"id": 13, "subject": "criminal", "question": "Ai sensi dell’art. 192, comma 3, c.p.p., le dichiarazioni rese da un imputato in un procedimento connesso o per un reato collegato possono essere utilizzate per valutare la responsabilità di un altro imputato?", "correct": "Sì, ma devono essere valutate insieme agli altri elementi di prova che ne confermano l’attendibilità.", "wrong": ["Sì, e possono da sole fondare la decisione, senza necessità di riscontri.", "No, perché le dichiarazioni rese da altri imputati non possono mai essere utilizzate come prova."]}, {"id": 14, "subject": "criminal", "question": "Entro quale termine la persona offesa può presentare opposizione alla richiesta di archiviazione per un delitto commesso con violenza alla persona o per il reato di cui all’art. 624-bis c.p.?", "correct": "Entro trenta giorni dalla notificazione dell’avviso della richiesta di archiviazione.", "wrong": ["Entro venti giorni dalla notificazione dell’avviso, come previsto in via generale per ogni richiesta di archiviazione.", "Entro dieci giorni dalla notificazione dell’avviso."]}, {"id": 15, "subject": "criminal", "question": "Ai sensi dell’art. 335, comma 3-bis, c.p.p., se sussistono specifiche esigenze investigative, per quanto tempo il pubblico ministero può disporre, con decreto motivato, il segreto sulle iscrizioni?", "correct": "Per un periodo non superiore a tre mesi, non rinnovabile.", "wrong": ["Per un periodo non superiore a due mesi, rinnovabile una sola volta.", "Per un periodo non superiore a un mese, rinnovabile senza limiti."]}, {"id": 16, "subject": "criminal", "question": "Ai sensi dell’art. 355 c.p.p., con quale provvedimento il pubblico ministero convalida il sequestro probatorio disposto dalla polizia giudiziaria?", "correct": "Con decreto motivato.", "wrong": ["Con ordinanza.", "Con sentenza."]}, {"id": 17, "subject": "criminal", "question": "Ai sensi dell’art. 393 c.p.p., chi può chiedere al giudice di procedere con incidente probatorio durante le indagini preliminari?", "correct": "Il pubblico ministero e la persona sottoposta alle indagini.", "wrong": ["Soltanto il pubblico ministero.", "Soltanto la persona sottoposta alle indagini."]}, {"id": 18, "subject": "criminal", "question": "33. Entro quale termine il pubblico ministero deve chiedere il giudizio immediato, ai sensi dell’art. 454 c.p.p., quando ricorrono i presupposti previsti dalla legge?", "correct": "Entro novanta giorni dalla data in cui la persona sottoposta alle indagini è stata identificata, nei casi previsti dalla legge.", "wrong": ["Entro quarantacinque giorni dall’iscrizione della notizia di reato.", "Entro novanta giorni dalla conclusione delle indagini preliminari, in ogni caso."]}, {"id": 19, "subject": "criminal", "question": "Quale dei seguenti non è un mezzo straordinario di impugnazione nel processo penale?", "correct": "L'appello.", "wrong": ["Il ricorso straordinario per errore materiale o di fatto.", "La revisione."]}, {"id": 20, "subject": "criminal", "question": "Qual è il giudice competente a decidere sulla richiesta di revisione di una sentenza penale?", "correct": "La Corte d’appello individuata secondo i criteri previsti dall’art. 11 c.p.p.", "wrong": ["La Corte d’assise che aveva eventualmente pronunciato la sentenza originaria.", "La Corte di cassazione in ogni caso."]}, {"id": 21, "subject": "criminal", "question": "Se l’imputato si rifiuta di sottoporsi all’esame, può comunque rendere dichiarazioni spontanee?", "correct": "Sì, il rifiuto di sottoporsi all’esame non esclude la possibilità di rendere dichiarazioni spontanee nei limiti previsti dalla legge.", "wrong": ["No, il rifiuto di sottoporsi all’esame comporta la perdita del diritto di rendere dichiarazioni spontanee.", "Sì, ma soltanto se l’imputato non ha ancora compiuto diciotto anni."]}, {"id": 22, "subject": "criminal", "question": "Quale autorità emette l’avviso di conclusione delle indagini preliminari previsto dall’art. 415-bis c.p.p.?", "correct": "Il pubblico ministero.", "wrong": ["Il giudice per le indagini preliminari.", "Il difensore della persona sottoposta alle indagini."]}, {"id": 23, "subject": "criminal", "question": "Ai sensi dell’art. 309 c.p.p., entro quale termine l’imputato può chiedere il riesame dell’ordinanza che dispone una misura cautelare coercitiva?", "correct": "Entro dieci giorni dall’esecuzione o dalla notificazione del provvedimento.", "wrong": ["Entro venti giorni dall’esecuzione o dalla notificazione del provvedimento.", "Entro un mese dall’esecuzione o dalla notificazione del provvedimento."]}, {"id": 24, "subject": "criminal", "question": "Ai sensi dell’art. 648 c.p.p., quando una sentenza penale diventa irrevocabile?", "correct": "Quando non è più soggetta a impugnazione ordinaria, perché non è impugnabile oppure perché sono scaduti i termini previsti dalla legge.", "wrong": ["Soltanto quando non è più possibile esperire alcun mezzo di impugnazione, ordinario o straordinario.", "Quando viene pronunciata dal giudice di primo grado, indipendentemente dalla possibilità di impugnarla."]}, {"id": 25, "subject": "criminal", "question": "Quanti difensori di fiducia può nominare l’imputato nel processo penale?", "correct": "Non più di due.", "wrong": ["Non più di tre.", "Non più di uno."]}, {"id": 26, "subject": "criminal", "question": "Quali obblighi disciplina l’art. 153_x001E_bis c.p.p. per la persona offesa querelante?", "correct": "La persona offesa querelante deve dichiarare o eleggere domicilio per le comunicazioni e notificazioni anche in un momento successivo alla presentazione della querela con possibilità di dichiarare un domicilio digitale (PEC o altro servizio elettronico di recapito certificato qualificato).", "wrong": ["La persona offesa querelante deve dichiarare o eleggere domicilio per le comunicazioni e notificazioni solo ed esclusivamente e obbligatoriamente al momento della presentazione della querela.", "Per la persona offesa querelante non è prevista una disciplina specifica distinta da quella prevista per la persona offesa non querelante."]}, {"id": 27, "subject": "criminal", "question": "Salvo che si proceda per delitti di criminalità organizzata o di terrorismo, l'intercettazione tra presenti mediante inserimento di captatore informatico su dispositivo elettronico portatile (trojan) nei luoghi di privata dimora (art. 614 c.p.) è ammessa?", "correct": "Sì, ma solo se vi è fondato motivo di ritenere che in tali luoghi si stia svolgendo l'attività criminosa, e per i delitti dei pubblici ufficiali contro la pubblica amministrazione puniti con la reclusione non inferiore nel massimo a 5 anni.", "wrong": ["Sì, ma solo se vi è fondato motivo di ritenere che in tali luoghi si stia svolgendo l'attività criminosa, e per i delitti dei pubblici ufficiali contro la pubblica amministrazione puniti con la reclusione superiore a 7 anni.", "Sì, ma solo per i delitti dei pubblici ufficiali contro la pubblica amministrazione puniti con la reclusione non inferiore nel massimo a 7 anni."]}, {"id": 28, "subject": "criminal", "question": "Quali sono le conseguenze se il Pubblico Ministero nega ingiustificatamente al difensore la trasposizione su supporto informatico delle registrazioni poste alla base di una misura cautelare personale?", "correct": "Si configura una nullità di ordine generale a regime intermediato, che inficia la tenuta del provvedimento cautelare.", "wrong": ["Si configura l'annullabilità  chenon  inficia la tenuta del provvedimento cautelare.", "Si configura una nullità di ordine generale a regime intermediato, senza conseguenze sul  provvedimento cautelare."]}, {"id": 29, "subject": "criminal", "question": "I risultati di intercettazioni regolarmente disposte nell'ambito di un procedimento penale possono essere utilizzati in un procedimento diverso?", "correct": "Sì, ma solo se risultano indispensabili per l'accertamento di delitti per i quali è previsto l'arresto obbligatorio in flagranza e per i reati di cui all'art. 266, comma 1, c.p.p., salvo quanto previsto per i reati di criminalità organizzata e terrorismo", "wrong": ["Sì, ma solo se risultano indispensabili per l'accertamento di delitti per i quali non  è previsto l'arresto obbligatorio in flagranza.", "Non possono mai  essere utilizzate in un procedimento diverso da quello nel quale sono state disposte."]}, {"id": 30, "subject": "criminal", "question": "In un procedimento per un reato comune intercettabile (es. truffa aggravata), qual è la durata massima dell'autorizzazione iniziale e delle singole proroghe introdotta dalle riforme più recenti?", "correct": "15 giorni la prima autorizzazione, prorogabile  illimitatamente  se persistono i presupposti.", "wrong": ["45 giorni la prima autorizzazione, prorogabile con decreto motivato per un solo ulteriore periodo di 45 giorni.", "45 giorni la prima autorizzazione, prorogabile con decreto motivato per periodi successivi di 15 giorni (salva la durata illimitata se persistono i presupposti)."]}, {"id": 31, "subject": "civil", "question": "Secondo quale principio che trova applicazione nel processo civile, spetta unicamente alle parti il  potere di fissare il thema decidendum, e cioè l'ambito di estensione e di limiti dell'oggetto del giudizio?", "correct": "Principio della corrispondenza tra chiesto e pronunciato.", "wrong": ["Obbligo di decidere secondo diritto.", "Regola di giudizio fondata sull'onere della prova."]}, {"id": 32, "subject": "civil", "question": "L'art. 116 c.p.c. stabilendo che il giudice deve valutare le prove secondo il suo prudente apprezzamento, salvo che la legge diponga altrimenti, quale principio sancisce?", "correct": "Principio della libera valutazione delle prove.", "wrong": ["Principio del contraddittorio.", "Principio dell'onere della prova."]}, {"id": 33, "subject": "civil", "question": "Come è determinata la  competenza per territorio La competenza per territorio per le azioni possessorie (art 21 cpc) e per la denuncia di nuova opera e di danno temuto?", "correct": "In base al luogo ove è avvenuto il fatto denunciato.", "wrong": ["In base a luogo della residenza o del domicilio dell'attore.", "In base al luogo di residenza o domicilio del convenuto."]}, {"id": 34, "subject": "civil", "question": "Quando diventa inefficace il  precetto?", "correct": "Se nel termine di 90 giorni dalla sua notifica non è iniziata l'esecuzione.", "wrong": ["Se nel termine di 45 giorni dalla sua notifica  non è iniziata l'esecuzione.", "Il precetto mantiene sempre la sua efficacia non essendo previsto un termine dalla notifica entro il quale debba essere iniziata l'esecuzione."]}, {"id": 35, "subject": "civil", "question": "A norma dell'art 547 cpc la dichiarazione del terzo nel procedimento di espropriazione presso terzi con che modalità viene effettuata?", "correct": "Con dichiarazione a mezzo raccomandata inviata al creditore procedente o trasmessa a mezzo di posta elettronica certificata.", "wrong": ["Con dichiarazione mezzo raccomandata inviata presso la cancelleria del giudice comptente.", "Con dichiarazione mezzo raccomandata inviata al debitore esecutato  o trasmessa a mezzo di posta elettronica certificata."]}, {"id": 36, "subject": "civil", "question": "A norma dell'art 163-bis cpc quale termine deve intercorrere tra il giorno della notifica della citazione e quello dell'udienza, se il luogo della notifica si trova in Italia?", "correct": "Debbono intercorrere termini liberi non minori di centoventi giorni.", "wrong": ["Debbono intercorrere termini liberi non minori di sessanta giorni.", "Debbono intercorrere termini  non minori di centoventi giorni, includendo nel computo il giorno della avvenuta notifica."]}, {"id": 37, "subject": "civil", "question": "Come deve essere proposto l'appello contro le sentenze pronunciate nei processi relativi alle controversie individuali di lavoro?", "correct": "Con ricorso dinanzi alla Corte di appello territorialmente competente in funzione di giudice del lavoro.", "wrong": ["Con atto di citazione dinanzi alla Corte di appello territorialmente competente in funzione di giudice del lavoro.", "Con atto di citazione dinanzi al Tribunale territorialmente competente in funzione di giudice del lavoro."]}, {"id": 38, "subject": "civil", "question": "Quale valore hanno le copie estratte telematicamente dal fascicolo informatico nei casi previsti dalla normativa sul processo civile telematico?", "correct": "Nei casi previsti dalla normativa, il difensore può estrarre copie e attestarne la conformità, con effetti equiparati all'originale secondo la disciplina vigente.", "wrong": ["Le copie estratte dal fascicolo informatico non possono mai essere utilizzate fuori dalla cancelleria e hanno soltanto valore informativo.", "Ogni copia estratta dal fascicolo informatico deve necessariamente essere autenticata dal cancelliere per poter essere prodotta in giudizio."]}, {"id": 39, "subject": "civil", "question": "Nel corso di una causa civile il difensore necessita di acquisire una copia di un provvedimento presente nel fascicolo informatico. Quale disciplina trova applicazione secondo la normativa vigente?", "correct": "Il difensore e gli altri soggetti abilitati possono estrarre duplicati e copie dal fascicolo informatico e, nei casi previsti dalla legge, attestarne la conformità con efficacia equiparata all'originale.", "wrong": ["La normativa consente, nei casi previsti, l'estrazione di copie e duplicati dal fascicolo informatico con gli effetti riconosciuti dalla legge, ma richiede sempre una preventiva autorizzazione scritta del cancelliere per qualsiasi documento presente nel fascicolo.", "La normativa consente, nei casi previsti, l'estrazione di copie e duplicati dal fascicolo informatico con gli effetti riconosciuti dalla legge, ma impone in ogni caso il rilascio materiale di una copia cartacea autenticata da parte della cancelleria."]}, {"id": 40, "subject": "civil", "question": "In un procedimento civile il giudice dispone che un'udienza sia sostituita dallo scambio e dal deposito di note scritte contenenti le sole istanze e conclusioni delle parti. Quale attività deve essere svolta dall'ufficio e quale effetto produce tale provvedimento?", "correct": "Quando il giudice dispone la trattazione scritta nei casi consentiti dalla legge, l'udienza è sostituita dal deposito di note scritte entro i termini stabiliti. La cancelleria cura le comunicazioni necessarie e le parti non sono tenute a comparire personalmente in udienza.", "wrong": ["Quando il giudice dispone la trattazione scritta nei casi consentiti dalla legge, l'udienza si considera sostituita dal deposito delle note entro i termini stabiliti. In tale ipotesi, la cancelleria provvede a trasmettere via PEC alle parti copia delle note depositate dalle altre parti prima che il giudice adotti i provvedimenti conseguenti.", "Quando il giudice dispone la trattazione scritta nei casi consentiti dalla legge, l'udienza si considera sostituita dal deposito delle note nei termini fissati dal provvedimento. La cancelleria deve però acquisire il consenso scritto di tutte le parti dopo ogni deposito affinché le note abbiano efficacia processuale."]}, {"id": 41, "subject": "civil", "question": "Nel processo civile chi assume la denominazione di rappresentante processuale?", "correct": "Chi agisce in nome e per conto altrui.", "wrong": ["Chi agisce in nome e per conto proprio.", "Chi agisce in nome proprio, ma per un diritto altrui."]}, {"id": 42, "subject": "civil", "question": "Nel procedimento semplificato di cognizione, quale termine minimo deve intercorrere tra la notificazione del ricorso e del decreto e l'udienza di comparizione, quando la notificazione avviene in Italia?", "correct": "Quaranta giorni liberi.", "wrong": ["Settanta giorni liberi.", "Novanta giorni liberi."]}, {"id": 43, "subject": "civil", "question": "Nel processo di cognizione ordinario  l'atto di citazione deve contenere l'invito al convenuto a costituirsi entro quale termine?", "correct": "Settanta giorni prima dell'udienza indicata.", "wrong": ["Venti giorni prima dell'udienza indicata.", "Trenta giorni prima dell'udienza indicata."]}, {"id": 44, "subject": "civil", "question": "Quali conseguenze implica l'omessa indicazione della data dell'udienza di comparizione e l'omessa o incerta indicazione delle parti nella citazione?", "correct": "In entrambi i casi la citazione è nulla.", "wrong": ["Nel primo caso la citazione è valida, nel secondo è annullabile.", "Nel primo caso la citazione è annullabile, nel secondo è valida."]}, {"id": 45, "subject": "civil", "question": "In quali casi una controversia civile può essere introdotta nelle forme del procedimento semplificato di cognizione previsto dagli artt. 281-decies e seguenti c.p.c.?", "correct": "Quando la causa è fondata su prova documentale, o di pronta soluzione, con fatti non controversi, e richiede un'istruttoria non complessa; inoltre, nelle cause monocratiche può essere utilizzato anche in assenza di tali presupposti.", "wrong": ["Soltanto nelle cause di valore inferiore a 50.000 euro e richiede sempre il consenso di tutte le parti; diversamente  deve essere seguito il rito ordinario.", "Esclusivamente nelle controversie che non richiedono attività istruttoria; la semplice necessità di assumere una prova testimoniale ne esclude l'utilizzo e impone il rito ordinario."]}, {"id": 46, "subject": "civil", "question": "Nel rito ordinario di cognizione, quali sono le principali attività che il giudice deve compiere alla prima udienza?", "correct": "Alla prima udienza il giudice verifica il contraddittorio, esamina le questioni preliminari, procede agli eventuali tentativi di conciliazione e adotta i provvedimenti necessari per la trattazione della causa, valutando anche le richieste istruttorie.", "wrong": ["Alla prima udienza il giudice deve necessariamente assumere tutte le prove richieste dalle parti e, conclusa l'istruttoria, pronunciare immediatamente la sentenza definitiva senza ulteriori rinvii di udienza.", "Alla prima udienza il giudice si limita a verificare il pagamento del contributo unificato e la regolarità formale degli atti depositati, non può esaminare questioni processuali o adottare provvedimenti sulla prosecuzione del giudizio. A tal fine fissa alle parti nuova udienza per la prosecuzione."]}, {"id": 47, "subject": "civil", "question": "Quali sono i principi fondamentali che regolano la fase introduttiva del rito ordinario di cognizione?", "correct": "Principio dell'iniziativa di parte, del contraddittorio, dell'impulso di parte.", "wrong": ["Principio della ragionevole durata del processo, della parità delle parti, del diritto di difesa.", "Principio della ragionevole durata del processo, del contraddittorio, del diritto di difesa."]}, {"id": 48, "subject": "civil", "question": "Quali sono gli obiettivi che caratterizzano  il principio di concentrazione e il principio di preclusione nella fase introduttiva del rito ordinario di cognizione?", "correct": "Il principio di concentrazione mira a far emergere e definire le questioni di fatto e di diritto in una fase processuale il più possibile anticipata, mentre il principio di preclusione impedisce alle parti di compiere determinate attività processuali una volta scaduti i termini stabiliti dalla legge.", "wrong": ["Il principio di concentrazione attribuisce al giudice il potere di decidere la causa senza contraddittorio, mentre il principio di preclusione impedisce alle parti di costituirsi in giudizio dopo la notificazione dell'atto di citazione.", "Il principio di concentrazione impone che tutte le udienze si svolgano nello stesso giorno, mentre il principio di preclusione consente alle parti di modificare liberamente domande ed eccezioni in qualunque momento del processo."]}, {"id": 49, "subject": "civil", "question": "Quale potere attribuisce l'art. 171-bis c.p.c. al giudice quando ritiene che ricorrano i presupposti per il rito semplificato di cognizione?", "correct": "Il giudice può disporre la prosecuzione del processo nelle forme del rito semplificato di cognizione e fissare la relativa udienza, assegnando alle parti i termini previsti dalla legge.", "wrong": ["Il giudice deve necessariamente dichiarare improcedibile la causa ordinaria e imporre l'introduzione di un nuovo giudizio.", "Il passaggio al rito semplificato può essere deciso esclusivamente dalla cancelleria al momento dell'iscrizione a ruolo."]}, {"id": 50, "subject": "civil", "question": "Quale innovazione  è stata stabilmente  introdotta dalla riforma in materia di udienze civili?", "correct": "La riforma ha disciplinato la sostituzione dell'udienza con il deposito di note scritte contenenti le sole istanze e conclusioni, nei casi previsti dalla legge e secondo la valutazione del giudice.", "wrong": ["La trattazione scritta è consentita soltanto nei procedimenti davanti al giudice di pace.", "La trattazione scritta ha eliminato definitivamente tutte le udienze civili in presenza."]}, {"id": 51, "subject": "civil", "question": "Nell'attuale disciplina processuale civile, in quali casi il giudice può disporre lo svolgimento dell'udienza con collegamento audiovisivo a distanza?", "correct": "Nei casi previsti dalla legge e quando ne ricorrono i presupposti, il giudice può disporre che l'udienza si svolga mediante collegamenti audiovisivi che garantiscano il contraddittorio e l'effettiva partecipazione dei soggetti coinvolti.", "wrong": ["Le udienze da remoto sono consentite esclusivamente nei procedimenti cautelari.", "Le udienze telematiche possono svolgersi soltanto con il consenso unanime di tutte le parti e del cancelliere."]}, {"id": 52, "subject": "civil", "question": "Quale funzione svolgono le memorie integrative previste dal nuovo sistema introdotto dalla riforma?", "correct": "Le memorie integrative consentono alle parti di precisare e modificare domande, eccezioni, conclusioni e richieste istruttorie nei termini stabiliti dalla legge, prima della prima udienza di comparizione.", "wrong": ["Le memorie integrative possono essere depositate soltanto dopo l'assunzione delle prove testimoniali.", "Le memorie integrative sono riservate esclusivamente ai procedimenti davanti alla Corte di cassazione."]}, {"id": 53, "subject": "civil", "question": "Ai sensi dell'art. 275 c.p.c., quale facoltà è riconosciuta alle parti nella fase decisoria davanti al tribunale in composizione collegiale?", "correct": "Ciascuna parte può chiedere, con la nota di precisazione delle conclusioni, che la causa sia discussa oralmente davanti al collegio.", "wrong": ["Ciascuna parte può chiedere che la sentenza sia pronunciata immediatamente all'udienza di rimessione della causa al collegio.", "Ciascuna parte può chiedere che la decisione sia rimessa direttamente alla Corte d'appello senza pronuncia del collegio."]}, {"id": 54, "subject": "civil", "question": "Come si propone l'appello civile contro una sentenza di primo grado?", "correct": "Con atto di citazione motivato, notificato alla controparte e successivamente iscritto a ruolo dall'appellante.", "wrong": ["Con ricorso depositato in cancelleria, che il giudice esamina e provvede poi a far notificare alla controparte.", "Con atto di citazione notificato alla controparte, con riserva di indicare in successiva memoria specifici motivi di impugnazione."]}, {"id": 55, "subject": "civil", "question": "Nel giudizio dinanzi alla Corte d'appello, chi decide la causa dopo la fase istruttoria?", "correct": "Il collegio, cui l'istruttore riserva la decisione.", "wrong": ["Il giudice istruttore con ordinanza definitiva.", "Il giudice istruttore, previa consultazione con il collegio, mediante decreto comunicato alle parti."]}, {"id": 56, "subject": "civil", "question": "Nel rito ordinario di cognizione, se una parte chiede la discussione orale della causa dinanzi al collegio, entro quale termine deve essere depositata la sentenza dopo lo svolgimento dell'udienza di discussione?", "correct": "Entro sessanta giorni dall'udienza di discussione davanti al collegio.", "wrong": ["Entro trenta giorni dall'udienza di discussione davanti al collegio.", "Entro sessanta giorni dalla richiesta di discussione orale presentata dalla parte."]}, {"id": 57, "subject": "civil", "question": "Quale requisito deve contenere, a pena di inammissibilità, ciascun motivo di appello?", "correct": "L'indicazione del capo impugnato e delle specifiche censure di fatto o di diritto.", "wrong": ["La trascrizione integrale della sentenza di primo grado impugnata.", "Esclusivamente l'indicazione delle prove delle quali si chiede la rinnovazione in appello."]}, {"id": 58, "subject": "civil", "question": "Quali sono le modalità di deposito degli accordi di negoziazione assistita (introdotta dal D.L. 132/2014 e aggiornata dalla Riforma Cartabia D.Lgs. 149/2022)", "correct": "Deposito telematico obbligatorio tramite il Processo Civile Telematico (PCT) o i software di redazione atti compatibili (SLPCT) inserendo l'atto nel registro \"Procura Civile\".", "wrong": ["Deposito telematico facoltativo tramite il Processo Civile Telematico (PCT) con esclusione dell'utilizzo di software di redazione atti compatibili (SLPCT).", "Deposito telematico obbligatorio nel protocollo informatico script@ indicando nell'oggetto \"negozoazione assisitita\"."]}, {"id": 59, "subject": "civil", "question": "Qual è la durata minima e massima della convenzione di negoziazione assistita, e cosa succede se le parti non specificano un termine?", "correct": "Il termine concordato non può essere inferiore a 1 mese né superiore a 3 mesi (prorogabile per ulteriori 30 giorni su accordo delle parti).", "wrong": ["Il termine concordato non può essere inferiore a 3 mesi né superiore a 6 mesi (prorogabile per ulteriori 60 giorni su accordo delle parti).", "Il termine concordato non può essere inferiore a 6 mesi né superiore a 9 mesi (prorogabile per ulteriori 45 giorni su accordo delle parti)."]}, {"id": 60, "subject": "civil", "question": "Qual è l'effetto processuale se una parte avvia un giudizio relativo a una materia in cui la negoziazione assistita è obbligatoria (es. risarcimento danni da circolazione di veicoli) senza aver prima formulato l'invito?", "correct": "L'improcedibilità dell'azione deve essere eccepita dal convenuto nella propria comparsa di risposta a pena di decadenza, oppure rilevata d'ufficio dal giudice non oltre la prima udienza.", "wrong": ["L'improcedibilità dell'azione deve essere eccepita solo nel corso del processo dal convenuto, non può essere rilevata d'ufficio dal giudice.", "L'azione è comunque procedibile non essendo previsto che il convenuto possa eccepire eccezioni , nè che sia rilevabile d'ufficio dal giudice."]}, {"id": 61, "subject": "registry", "question": "Ai sensi dell'art. 75, comma 1, del D.P.R. n. 115/2002, l'ammissione al patrocinio a spese dello Stato conserva la propria efficacia:", "correct": "Per ogni fase e grado del processo.", "wrong": ["Esclusivamente per la fase in cui è stata concessa.", "Fino al compimento del primo atto successivo all'ammissione."]}, {"id": 62, "subject": "registry", "question": "Nel processo civile, in caso di dichiarazione di inammissibilità dell'istanza di ammissione al patrocinio a spese dello Stato da parte del Consiglio dell'Ordine, la parte può riproporre l'istanza?", "correct": "Sì, al magistrato competente per il giudizio, che decide con decreto.", "wrong": ["No, il rigetto del Consiglio dell'Ordine è definitivo.", "Sì, al cancellerie dell'ufficio giudiziario che decide con ordinanza."]}, {"id": 63, "subject": "registry", "question": "In caso di ammissione al patrocinio a spese dello Stato, come viene trattata la spesa del contributo unificato nel processo civile?", "correct": "Viene prenotata a debito.", "wrong": ["Viene anticipata dall'erario.", "Viene posta a carico del difensore."]}, {"id": 64, "subject": "registry", "question": "Le spese forfettizzate per le notificazioni a richiesta d'ufficio nel processo civile, in caso di ammissione al patrocinio a spese dello Stato, come vengono imputate?", "correct": "Sono prenotate a debito.", "wrong": ["Sono anticipate dall'erario.", "Sono poste a carico del difensore."]}, {"id": 65, "subject": "registry", "question": "Nel processo civile, gli onorari e le spese spettanti al difensore della parte ammessa al patrocinio a spese dello Stato sono qualificati come spese:", "correct": "Anticipate dall'erario.", "wrong": ["Prenotate a debito.", "Escluse dal patrocinio."]}, {"id": 66, "subject": "registry", "question": "Quando il giudice condanna una parte non ammessa al patrocinio a rifondere le spese processuali sostenute da una parte ammessa al beneficio,a favore di chi deve essere eseguito  il pagamento?", "correct": "A favore dello Stato.", "wrong": ["Alla favore della parte ammessa al patrocinio.", "A favore del  difensore della parte ammessa al patrocinio."]}, {"id": 67, "subject": "registry", "question": "Nel processo civile, in caso di cancellazione della causa dal ruolo ai sensi dell'art. 309 c.p.c., chi è tenuto al pagamento delle spese prenotate a debito?", "correct": "Tutte le parti in solido.", "wrong": ["La sola parte non ammessa al patrocinio.", "La sola parte attrice."]}, {"id": 68, "subject": "registry", "question": "Ai sensi dell'art. 136, comma 1, TUSG, la sopravvenienza di modifiche reddituali rilevanti ai fini dell'ammissione al patrocinio a spese dello stato, comporta:", "correct": "La revoca dell'ammissione al patrocinio a spese dello Stato.", "wrong": ["L'automatica sospensione del beneficio.", "La necessità di presentare una nuova istanza senza revoca."]}, {"id": 69, "subject": "registry", "question": "Nel corso di un procedimento civile, il magistrato accerta che l'ammissione al patrocinio a spese dello Stato è stata concessa in assenza dei requisiti previsti dalla legge. Quale decisione  deve adottare?", "correct": "Revoca l'ammissione al patrocinio.", "wrong": ["Trasmette gli atti al Consiglio dell'Ordine per una nuova valutazione.", "Sospende il beneficio fino alla conclusione del processo."]}, {"id": 70, "subject": "registry", "question": "Trascorsi quanti anni le somme di denaro depositate presso Poste Italiane s.p.a., banche ed altri operatori finanziari, in relazione a procedimenti civili di cognizione, esecutivi o speciali, non riscossi o non reclamati dagli aventi diritto confluiscono nel F.U.G.?", "correct": "Cinque anni.", "wrong": ["Tre anni.", "Sette anni."]}, {"id": 71, "subject": "registry", "question": "Per le risorse affluenti al F.U.G. e per i casi di devoluzione di tali risorse, gli uffici giudiziari procedenti sono tenuti a curare le relative comunicazioni con la società Equitalia Giustizia?", "correct": "Si, ivi comprese le restituzioni e le confische.", "wrong": ["Sì, ad esclusione delle restituzioni e delle confische.", "Sì, ivi comprese le confische, con esclusione delle restituzioni."]}, {"id": 72, "subject": "registry", "question": "I registri dei depositi giudiziari, i registri Modello II e III:", "correct": "Sono prescritti solo presso la cancelleria del Tribunale ove si svolgono le procedure inerenti l'esecuzione immobiliare.", "wrong": ["Sono istituiti presso tutti gli uffici giudiziari di ogni ordine e grado.", "Sono istituiti solo presso gli uffici della magistratura requirente."]}, {"id": 73, "subject": "registry", "question": "Ai sensi dell'art. 158, comma 1, TUSG, le spese gravanti su un'amministrazione pubblica parte del processo civile sono:", "correct": "Spese prenotate a debito.", "wrong": ["Spese anticipate dall'erario.", "Recuperate immediatamente nei confronti della controparte"]}, {"id": 74, "subject": "registry", "question": "Nel processo civile in cui è parte un'amministrazione pubblica, se questa ottiene la condanna della controparte alla rifusione delle spese processuali, le spese prenotate a debito e anticipate dall'erario:", "correct": "Sono recuperate dall'amministrazione.", "wrong": ["Sono recuperate dalla cancelleria.", "Restano definitivamente a carico dell'erario."]}, {"id": 75, "subject": "registry", "question": "Secondo l'art. 14, comma 3.1, del d.P.R. n. 115/2002, come modificato dalla legge di bilancio 2025, quale importo minimo deve risultare versato affinché una causa civile possa essere iscritta a ruolo, salvo i casi di esenzione?", "correct": "L'importo determinato ai sensi dell'art. 13, comma 1, lettera a), del d.P.R. n. 115/2002, pari a euro 43,00, ovvero il minor contributo previsto dalla legge.", "wrong": ["Almeno la metà del contributo unificato dovuto in relazione al valore della causa, con obbligo di integrare il versamento prima della prima udienza.", "Qualsiasi importo a titolo di contributo unificato, purché la differenza venga recuperata dall'amministrazione successivamente all'iscrizione a ruolo."]}, {"id": 76, "subject": "registry", "question": "Ai sensi dell'art. 13 del D.M. 44/2011, quando si intende ricevuto dal dominio giustizia un atto o documento informatico trasmesso telematicamente da un soggetto abilitato esterno?", "correct": "Nel momento in cui viene generata la conferma della trasmissione secondo le specifiche tecniche previste dalla normativa.", "wrong": ["Nel momento in cui il cancelliere accetta il deposito ed esegue materialmente l'iscrizione dell'atto nel registro informatico dell'ufficio giudiziario.", "Nel momento in cui il magistrato prende visione dell'atto depositato e ne autorizza l'acquisizione al fascicolo processuale."]}, {"id": 77, "subject": "registry", "question": "Nel processo civile, la parte costituita può ottenere copia degli atti e dei documenti contenuti nel fascicolo d'ufficio?", "correct": "Sì, la parte costituita può chiedere ed estrarre copia degli atti e dei documenti secondo le modalità previste dalla legge e previo pagamento dei diritti dovuti, ove previsti.", "wrong": ["Sì, ma soltanto previa autorizzazione del magistrato che procede, indipendentemente dalla natura degli atti richiesti.", "No, il diritto di ottenere copia degli atti del fascicolo è riservato esclusivamente ai difensori iscritti all'albo degli avvocati."]}, {"id": 78, "subject": "registry", "question": "Ai sensi dell'art. 196-quater disp. att. c.p.c., quando può essere autorizzato il deposito degli atti con modalità non telematiche?", "correct": "Quando ricorre una situazione di urgenza e il Direttore generale per i sistemi informativi automatizzati del Ministero della giustizia ha certificato il malfunzionamento dei sistemi informatici del dominio giustizia; in tal caso l'autorizzazione è rilasciata dal capo dell'ufficio.", "wrong": ["Quando il difensore dichiara di essere impossibilitato ad utilizzare gli strumenti informatici necessari per il deposito telematico.", "Quando il giudice ritiene che il deposito cartaceo sia più agevole per l'esame della controversia, anche in assenza di malfunzionamenti dei sistemi informatici."]}, {"id": 79, "subject": "registry", "question": "Nel processo civile, il cancelliere è tenuto a comunicare il deposito della sentenza alla parte contumace?", "correct": "No. Il cancelliere dà immediata comunicazione del deposito della sentenza soltanto alle parti che si sono costituite in giudizio.", "wrong": ["Sì. Il cancelliere deve comunicare il deposito della sentenza sia alle parti costituite sia a quelle contumaci, al fine di consentire l'esercizio del diritto di impugnazione.", "Sì, ma soltanto quando la sentenza definisce il giudizio con accoglimento totale delle domande proposte nei confronti della parte contumace."]}, {"id": 80, "subject": "registry", "question": "Entro quale termine la dichiarazione di accettazione dell'eredità con beneficio d'inventario deve essere trascritta presso l'ufficio dei registri immobiliari?", "correct": "Entro un mese dall'inserzione della dichiarazione nel registro delle successioni, a cura del cancelliere.", "wrong": ["Entro novanta giorni dalla redazione dell'inventario, indipendentemente dalla data di inserzione della dichiarazione nel registro delle successioni.", "Entro un anno dall'apertura della successione, a cura dell'erede che ha reso la dichiarazione di accettazione con beneficio d'inventario."]}, {"id": 81, "subject": "registry", "question": "Entro quale termine il cancelliere deve richiedere la trascrizione degli atti e dei provvedimenti soggetti a pubblicità immobiliare da lui ricevuti o ai quali abbia partecipato?", "correct": "Entro centoventi giorni dalla data dell'atto o del provvedimento, ovvero dalla sua pubblicazione quando questa è prescritta.", "wrong": ["Entro sessanta giorni dalla data dell'atto o del provvedimento, analogamente a quanto previsto per il certificato di successione.", "Entro trenta giorni dalla data dell'atto o del provvedimento, secondo il termine previsto per i notai e gli altri pubblici ufficiali."]}, {"id": 82, "subject": "registry", "question": "Ai sensi dell'art. 58 c.p.c., quale attività di conservazione è attribuita al cancelliere?", "correct": "La conservazione dei fascicoli delle parti e la formazione del fascicolo d'ufficio.", "wrong": ["La conservazione esclusiva del fascicolo del giudice, mentre i fascicoli di parte restano nella disponibilità dei difensori.", "La conservazione dei soli fascicoli relativi ai procedimenti definiti con sentenza passata in giudicato."]}, {"id": 83, "subject": "registry", "question": "Secondo l'art. 58 c.p.c., a chi compete l'iscrizione delle cause a ruolo?", "correct": "Al cancelliere.", "wrong": ["Al giudice designato per la trattazione della causa.", "Alla parte che ha promosso il giudizio mediante deposito di apposita istanza."]}, {"id": 84, "subject": "registry", "question": "Le controversie di valore non superiore a euro 1.033,00 e gli atti e provvedimenti ad esse relativi sono soggetti all'imposta di registro?", "correct": "No. Le controversie di valore non eccedente euro 1.033,00 e gli atti e provvedimenti ad esse relativi beneficiano dell'esenzione dall'imposta di registro, indipendentemente dal grado di giudizio, dall'ufficio giudiziario adito e dal tipo di processo instaurato.", "wrong": ["Sì, salvo che si tratti di provvedimenti emessi dal Giudice di pace nel solo giudizio di primo grado.", "No, ma l'esenzione opera esclusivamente nei giudizi di cognizione e non si estende ai procedimenti esecutivi o cautelari."]}, {"id": 85, "subject": "registry", "question": "In sede di iscrizione a ruolo di una procedura esecutiva fondata su un credito di lavoro, quale verifica deve effettuare la cancelleria ai fini del contributo unificato?", "correct": "Deve verificare se il creditore supera il limite reddituale previsto dall'art. 9, comma 1-bis, del d.P.R. n. 115/2002, poiché l'esenzione dal contributo unificato non è assoluta ma subordinata alla condizione reddituale della parte.", "wrong": ["Deve considerare la procedura esecutiva sempre esente dal contributo unificato, in quanto relativa a un credito di lavoro.", "Deve richiedere il contributo unificato in ogni caso, indipendentemente dal reddito della parte procedente."]}, {"id": 86, "subject": "registry", "question": "Ai fini dell'imposta di registro, il cancelliere deve trasmettere all'Agenzia delle Entrate il decreto ingiuntivo dichiarato esecutivo avente ad oggetto crediti di lavoro?", "correct": "No. I provvedimenti relativi alle controversie individuali di lavoro e ai rapporti di pubblico impiego sono esenti dall'imposta di registro ai sensi dell'articolo 10 della legge n. 319/1958.", "wrong": ["Sì. Tutti i decreti ingiuntivi dichiarati esecutivi devono essere trasmessi all'Agenzia delle Entrate per la registrazione, indipendentemente dalla materia trattata.", "Sì, ma soltanto quando il credito azionato supera l'importo previsto per l'esenzione dal contributo unificato."]}, {"id": 87, "subject": "registry", "question": "Ai sensi dell'art. 73, comma 2-ter, del d.P.R. n. 115/2002, entro quale termine il cancelliere deve richiedere la registrazione delle sentenze e degli altri atti recanti condanna al risarcimento del danno prodotto da fatti costituenti reato?", "correct": "Entro trenta giorni dalla data in cui la sentenza o l'atto sono divenuti definitivi.", "wrong": ["Entro trenta giorni dalla pubblicazione della sentenza, indipendentemente dal suo passaggio in giudicato.", "Entro sessanta giorni dalla comunicazione del provvedimento alle parti."]}, {"id": 88, "subject": "registry", "question": "il rilascio di una copia autentica di un provvedimento giudiziario richiesta da una parte processuale è soggetto all'imposta di bollo?", "correct": "No. Le copie autentiche richieste dalle parti processuali non sono soggette all'imposta di bollo.", "wrong": ["Sì. Le copie autentiche sono sempre soggette all'imposta di bollo, salvo che si tratti di procedimenti penali.", "No. Le copie autentiche sono esenti dall'imposta di bollo soltanto quando vengono rilasciate dal giudice e non dalla cancelleria."]}, {"id": 89, "subject": "registry", "question": "Ai sensi dell'art. 269 del d.P.R. n. 115/2002, è dovuto il diritto di copia quando il soggetto abilitato estrae direttamente dal fascicolo informatico una copia senza certificazione di conformità?", "correct": "No. Il diritto di copia senza certificazione di conformità non è dovuto quando la copia è estratta direttamente dal fascicolo informatico dai soggetti abilitati ad accedervi.", "wrong": ["Sì. Il diritto di copia è sempre dovuto, indipendentemente dalle modalità di estrazione del documento e dalla presenza o meno della certificazione di conformità.", "Sì, ma in misura ridotta rispetto a quella prevista per le copie rilasciate su supporto cartaceo."]}, {"id": 90, "subject": "registry", "question": "Quale contributo unificato si applica ai reclami disciplinati dall'art. 51 del Codice della crisi d'impresa e dell'insolvenza (d.lgs. n. 14/2019)?", "correct": "Si applica il contributo unificato determinato in base al valore della causa, considerato indeterminabile ai sensi dell'art. 13, comma 1, lett. d), d.P.R. n. 115/2002, con la maggiorazione prevista per i giudizi di impugnazione.", "wrong": ["Si applica il contributo unificato in misura fissa previsto per i procedimenti di volontaria giurisdizione, senza alcuna maggiorazione poiché il reclamo ex art. 51 CCII non costituisce un'impugnazione in senso proprio.", "Si applica il contributo unificato previsto per i procedimenti in camera di consiglio ex art. 13, comma 1, lett. b), d.P.R. n. 115/2002, aumentato della metà ai sensi dell'art. 13, comma 1-bis."]}, {"id": 91, "subject": "registry", "question": "Come deve comportarsi la cancelleria quando, al momento dell'iscrizione a ruolo di una causa civile, è pendente una domanda di ammissione al patrocinio a spese dello Stato sulla quale il Consiglio dell'Ordine degli Avvocati non si è ancora pronunciato?", "correct": "La cancelleria deve procedere all'iscrizione a ruolo senza richiedere il pagamento del contributo unificato, purché l'avvocato alleghi l'istanza di ammissione regolarmente depositata e protocollata presso il competente Consiglio dell'Ordine; deve inoltre aprire il foglio notizie e, in caso di rigetto dell'istanza non confermato dal magistrato, procedere alla riscossione delle spese annotate.", "wrong": ["La cancelleria deve iscrivere il procedimento a ruolo richiedendo comunque l'immediato pagamento del contributo unificato, con eventuale successivo rimborso in caso di ammissione al patrocinio a spese dello Stato.", "La cancelleria deve sospendere l'iscrizione a ruolo fino alla decisione del Consiglio dell'Ordine degli Avvocati sull'istanza di ammissione al patrocinio a spese dello Stato."]}, {"id": 92, "subject": "registry", "question": "Come deve essere versato il contributo unificato quando il giudizio per l'accertamento della cittadinanza italiana è promosso da più ricorrenti con un unico ricorso introduttivo?", "correct": "Ciascun ricorrente deve versare autonomamente il contributo unificato di euro 600,00 previsto dall'art. 13, comma 1-sexies, del d.P.R. n. 115/2002.", "wrong": ["Il contributo unificato di euro 600,00 è dovuto una sola volta per il ricorso, indipendentemente dal numero dei ricorrenti.", "Nei procedimenti di accertamento della cittadinanza italiana il contributo unificato non è dovuto quando vi sono più ricorrenti che agiscono congiuntamente."]}, {"id": 93, "subject": "registry", "question": "Quale regime si applica al contributo unificato nei procedimenti di descrizione, sequestro e inibitoria disciplinati dagli artt. 129 e 131 del Codice della proprietà industriale?", "correct": "Si applica il contributo unificato previsto dall'art. 13, comma 1-ter, del d.P.R. n. 115/2002, con raddoppio dell'importo in quanto procedimenti attribuiti alla competenza delle sezioni specializzate in materia di impresa.", "wrong": ["Si applica il contributo unificato dimezzato previsto dall'art. 13, comma 3, del d.P.R. n. 115/2002, poiché gli artt. 129 e 131 del Codice della proprietà industriale richiamano le norme sui procedimenti cautelari del codice di procedura civile.", "Si applica il dimezzamento del contributo unificato previsto dall'art. 13, comma 3, del d.P.R. n. 115/2002 per tutti i processi speciali del Libro IV, Titolo I, c.p.c., in quanto i procedimenti di descrizione, sequestro e inibitoria hanno natura cautelare."]}, {"id": 94, "subject": "registry", "question": "Quale attività compete all'ufficio giudiziario quando riceve un'istanza di rimborso dei diritti di copia o di certificato indebitamente versati?", "correct": "L'ufficio giudiziario deve verificare la fondatezza della richiesta, rilasciare il nulla osta attestando l'indebito o l'eccedenza del pagamento, acquisire la certificazione relativa all'imputazione contabile delle somme e trasmettere la pratica all'amministrazione competente al rimborso.", "wrong": ["L'ufficio giudiziario deve limitarsi a verificare l'avvenuto pagamento e trasmettere immediatamente l'istanza al Ministero dell'economia e delle finanze, senza svolgere ulteriori attività istruttorie.", "L'ufficio giudiziario è sempre tenuto a disporre direttamente il rimborso in favore dell'istante mediante accredito sul conto corrente indicato nella domanda."]}, {"id": 95, "subject": "registry", "question": "Quale trattamento fiscale si applica al rilascio del certificato previsto dall'art. 39 del Regolamento (CE) n. 2201/2003 (Bruxelles II bis)?", "correct": "Per il rilascio del certificato è dovuto il diritto di certificato secondo gli importi previsti dall'art. 273 del d.P.R. n. 115/2002, non essendo applicabile l'esenzione prevista dall'art. 19 della legge n. 74/1987 per i procedimenti di separazione e divorzio.", "wrong": ["Poiché il certificato è rilasciato nell'ambito di controversie in materia matrimoniale o di responsabilità genitoriale, trova applicazione l'esenzione fiscale prevista per gli atti e i provvedimenti relativi ai procedimenti di separazione e divorzio.", "Il rilascio del certificato europeo ex art. 39 del Regolamento (CE) n. 2201/2003 è sempre gratuito e non richiede il pagamento di alcun diritto di certificato."]}, {"id": 96, "subject": "registry", "question": "Come deve essere gestita l'imposta di registro dovuta sull'ordinanza di assegnazione emessa nell'ambito di una procedura esecutiva nei confronti di un'Amministrazione dello Stato?", "correct": "Nelle procedure esecutive promosse contro un'Amministrazione dello Stato, l'imposta di registro dovuta sull'ordinanza di assegnazione deve essere prenotata a debito, poiché il meccanismo previsto dall'art. 158 del d.P.R. n. 115/2002 si estende anche alla fase esecutiva.", "wrong": ["L'imposta di registro deve essere anticipata dal creditore procedente, che potrà successivamente richiederne il rimborso all'Amministrazione debitrice mediante autonoma istanza amministrativa.", "Nelle procedure esecutive promosse contro le amministrazioni dello Stato non è dovuta alcuna imposta di registro sulle ordinanze di assegnazione, in ragione della natura pubblica del debitore esecutato."]}, {"id": 97, "subject": "registry", "question": "L'onere delle spese nel processo civile grava in via generale:", "correct": "Sulla parte tenuta ad anticiparle secondo legge.", "wrong": ["Su entrambe le parti in eguale misura, salvo che il giudice disponga diversamente con provvedimento motivato.", "Sul soggetto che risulterà soccombente."]}, {"id": 98, "subject": "registry", "question": "Ai sensi dell'art. 9 del d.P.R. n. 115/2002, il contributo unificato di iscrizione a ruolo è dovuto:", "correct": "Per ciascun grado di giudizio nel processo civile, compresa la procedura concorsuale e la volontaria giurisdizione, salvo i casi di esenzione espressamente previsti dalla legge.", "wrong": ["Esclusivamente nei procedimenti contenziosi di cognizione ordinaria, con esclusione della volontaria giurisdizione e delle procedure concorsuali.", "Soltanto nei giudizi di impugnazione, essendo destinato a finanziare l'attività degli uffici giudiziari di secondo grado."]}, {"id": 99, "subject": "registry", "question": "Nei procedimenti di interdizione e di inabilitazione promossi dal Pubblico Ministero, lo Stato può esercitare il diritto di ripetizione delle spese nei confronti del tutore o del curatore nominato, nella qualità?", "correct": "Si, se il magistrato con decreto accerta il superamento dei limiti di reddito\nprevisti per l'ammissione al\npatrocinio.", "wrong": ["No.", "Si, anche se il magistrato non\naccerta il superamento dei\nlimiti di reddito previsti per\nl'ammissione al patrocinio."]}, {"id": 100, "subject": "registry", "question": "Dell'apertura e della chiusura della tutela\nil cancelliere dà comunicazione\nall'ufficiale dello stato civile per\nl'annotazione in margine all'atto di\nnascita del minore o dell'interdetto entro:", "correct": "Dieci giorni.", "wrong": ["Venti giorni.", "Cinque giorni."]}, {"id": 101, "subject": "registry", "question": "Il registro delle successioni consta di tre\nparti; nella terza sono\nregistrate/registrati:", "correct": "I provvedimenti di nomina dei curatori\ndelle eredità giacenti, e gli atti relativi alla\ncuratela e le dichiarazioni di\naccettazione o di rinunzia degli\nesecutoritestamentari.", "wrong": ["Le dichiarazioni di accettazione\ndell'eredità con beneficio d'inventario.", "Le dichiarazioni di rinunzia all'eredità."]}, {"id": 102, "subject": "registry", "question": "Il registro delle successioni:", "correct": "Contiene, tra l'altro,\nle dichiarazioni di\naccettazione\ndell'eredità con\nbeneficio\nd'inventario.", "wrong": ["Contiene solo le\ndichiarazioni di\nrinunzia all'eredità.", "A differenza degli\naltri registri\ndell'applicativo SICID\n- Volontaria non può\nessere esaminato da\nchiunque ne faccia\ndomanda."]}, {"id": 103, "subject": "registry", "question": "La dichiarazione di accettazione\ndell'eredità con beneficio d'inventario:", "correct": "Deve essere\npreceduta o seguita\ndall'inventario.", "wrong": ["Deve essere ricevuta\nda un notaio o dal\nfunzionario del\ntribunale del\ncircondario eletto\ndall'erede o dagli\neredi.", "Deve essere\ntrascritta a cura\ndell'ufficio, entro tre\nmesi dall'inserzione,\npresso la\nConservatoria dei\nregistri immobiliari\ndel luogo in cui si è\naperta la\nsuccessione."]}, {"id": 104, "subject": "registry", "question": "In base all'art. 3 del d.P.R. n. 313/2002, i provvedimenti definitivi di interdizione e inabilitazione sono iscritti nel Casellario giudiziale?", "correct": "Sì, i provvedimenti definitivi di interdizione e di inabilitazione sono soggetti a iscrizione nel Casellario giudiziale.", "wrong": ["Sì, ma soltanto quando il provvedimento di interdizione o di inabilitazione riguarda soggetti condannati in sede penale.", "No, poiché nel Casellario giudiziale sono iscritti esclusivamente i provvedimenti dell'autorità giudiziaria aventi natura penale."]}, {"id": 105, "subject": "registry", "question": "Il cancelliere può rilasciare copia di un\ndocumento impugnato di falso?", "correct": "Sì,il cancelliere è tenuto a rilasciare copia di un documento impugnato di falso se è stato autorizzato dal giudice istruttore.", "wrong": ["Si, il cancelliere è\ntenuto a rilasciare\ncopia di documento\nimpugnato di falso se\nlegittimamente\nrichiesto dalla parte.", "Si, se il documento è\nstato registrato."]}, {"id": 106, "subject": "registry", "question": "Per quanto tempo gli uffici giudiziari sono tenuti a conservare le produzioni di parte e gli altri documenti acquisiti nei procedimenti civili?", "correct": "Per tre anni dalla decisione o, comunque, dalla definizione della lite, in conformità al principio desumibile dall'art. 2961 c.c.", "wrong": ["Fino a quando le esigenze organizzative dell'ufficio lo consentano, potendo la documentazione essere eliminata anticipatamente in caso di carenza di spazi destinati all'archiviazione.", "Per dieci anni dalla definizione del procedimento, in applicazione del termine ordinario di prescrizione previsto dal codice civile."]}, {"id": 107, "subject": "registry", "question": "Da chi viene rilasciato il certificato indicato nell’art. 39 Regolamento (CE) n.2201/2003 relativo alla competenza, al riconoscimento e all’esecuzione delle decisioni in materia matrimoniale e in materia di responsabilità genitoriale?", "correct": "E' un attestato rilasciato dal Tribunale, dalla Procura della Repubblica  o dall’autorità che ha emesso il provvedimento utilizzando i modelli standard allegati al regolamento.", "wrong": ["E' un attestato rilasciato direttamente dal Dipartimento dell'organizzazione giudiziaria, del personale e dei servizi del Ministero della Giustizia utilizzando modelli standard allegati al regolamento.", "E' un attestato rilasciato direttamente dal Dipartimento per la giustizia minorile e di comunità del Ministero della Giustizia utilizzando i modelli standard dallo stesso predisposti."]}, {"id": 108, "subject": "registry", "question": "Le cose sequestrate custodite presso la cancelleria, in quale registro sono annotate?", "correct": "Le cose sequestrate custodite presso la cancelleria sono annotate nell'apposito Registro dei Corpi di Reato - Mod. 41.", "wrong": ["Le cose sequestrate custodite presso la cancelleria sono annotate nell'apposito Registro FUG.", "Le cose sequestrate custodite presso la cancelleria sono annotate nell'apposito Registro Mod. 42."]}, {"id": 109, "subject": "registry", "question": "A seguito dell'introduzione nel settore penale del registro informatico denominato SICP (Sistema Informativo della Cognizione Penale), come vengono registrati i corpi di reato ordinari e quelli di valore?", "correct": "I corpi di reato ordinari e quelli di valore sono registrati senza distinzione di numerazione, in un apposito campo nel quale vengono riportati i dati di riferimento.", "wrong": ["I corpi di reato ordinari e quelli di valore sono registrati con numerazione autonoma e in campi diversi.", "I corpi di reato ordinari e quelli di valore sono registrati nel registro delle cose sequestrate affidate in custodia a terzi."]}, {"id": 110, "subject": "registry", "question": "Nella procedura di vendita di beni sottoposti a sequestro penale, quali spese sono anticipate dall'Erario?", "correct": "Le spese di spedizione o l'indennità di trasferta degli ufficiali giudiziari per le notificazioni civili a richiesta d'ufficio; le spese e gli onorari agli ausiliari del magistrato; l'indennità di custodia; le spese per gli strumenti di pubblicità dei provvedimenti dell'autorità giudiziaria.", "wrong": ["Il contributo unificato e i diritti di copia.", "Le spese per il mantenimento dei detenuti, le ammende penali e le sanzioni pecuniarie inflitte dal giudice."]}, {"id": 111, "subject": "registry", "question": "Il certificato del casellario giudiziale europeo contiene anche l'attestazione relativa alla sussistenza o meno di iscrizioni nel casellario giudiziale?", "correct": "Sì.", "wrong": ["Dipende dalla richiesta effettuata, che può includere o meno le iscrizioni indicate dalla norma.", "No, salvo espressa richiesta motivata da ragioni di urgenza."]}, {"id": 112, "subject": "registry", "question": "A chi deve essere presentata l'istanza di ammissione al patrocinio a spese dello stato nel processo penale?", "correct": "Al magistrato davanti al quale pende il processo o che procede.", "wrong": ["Al Consiglio dell'Ordine degli Avvocati.", "Al Ministero della Giustizia."]}, {"id": 113, "subject": "registry", "question": "Quale dei seguenti soggetti può essere ammesso al patrocinio a spese dello Stato nel processo penale?", "correct": "L'imputato, la persona offesa dal reato, il danneggiato che intende costituirsi parte civile e il responsabile civile possono chiedere di essere ammessi al patrocinio a spese dello Stato, secondo le norme della legge sul patrocinio dei non abbienti.", "wrong": ["Solo l'imputato.", "Soltanto la persona offesa."]}, {"id": 114, "subject": "registry", "question": "Entro quanti giorni deve essere richiesta la registrazione della sentenza di condanna al risarcimento del danno prodotto da fatti costituenti reato?", "correct": "Trenta giorni dal passaggio in giudicato.", "wrong": ["Dieci giorni dalla notifica.", "Quindici giorni dalla data di annotazione."]}, {"id": 115, "subject": "registry", "question": "Per l'imputato militare in servizio attivo, come viene eseguita la prima notificazione quando il suo stato risulta dagli atti ?", "correct": "Nel luogo in cui l'imputato risiede per ragioni di servizio mediante consegna alla persona; se la consegna non è possibile, l'atto è notificato presso l'ufficio del comandante, che informa immediatamente l'interessato con il mezzo più celere.", "wrong": ["Presso il comune di nascita dell'imputato mediante deposito dell'atto nella casa comunale.", "Presso l'ufficio del comandante, che può delegare qualsiasi militare alla consegna dell'atto."]}, {"id": 116, "subject": "registry", "question": "Cosa deve fare la cancelleria del giudice che ha pronunciato una sentenza penale nei confronti di un lavoratore dipendente di una pubblica amministrazione ?", "correct": "Comunicare il dispositivo della sentenza all'amministrazione di appartenenza del dipendente e, su richiesta di questa, trasmettere copia integrale del provvedimento.", "wrong": ["Trasmettere automaticamente la copia integrale della sentenza al Ministero della Giustizia senza alcuna richiesta dell'amministrazione interessata.", "Inviare esclusivamente il certificato del casellario giudiziale all'amministrazione di appartenenza del dipendente."]}, {"id": 117, "subject": "registry", "question": "Nel sottofascicolo relativo  a ciascun indagato o imputato sottoposto a misura cautelare in carcere o agli arresti domiciliari, quali atti vengono raccolti?", "correct": "Le copie dell'ordinanza con cui la misura è stata adottata, il relativo verbale di esecuzione e tutti gli atti che incidono sulla durata, sulla modifica o sulla cessazione della misura.", "wrong": ["Esclusivamente le richieste del pubblico ministero e le memorie difensive presentate nel procedimento.", "Tutti gli atti dell'intero procedimento penale, comprese le intercettazioni e i verbali di udienza."]}, {"id": 118, "subject": "registry", "question": "In caso di ricorso per Cassazione, dove deve essere trattenuto il sottofascicolo relativo all' imputato sottoposto alla misura cautelare in carcere o agli arresti domiciliari ?", "correct": "Presso la cancelleria del giudice che ha emesso la sentenza impugnata.", "wrong": ["Presso la cancelleria della Corte di Cassazione fino alla decisione del ricorso.", "Presso la segreteria del pubblico ministero che ha richiesto la misura cautelare."]}, {"id": 119, "subject": "registry", "question": "A decorrere dal 1° gennaio 2009, quale registro sostituisce il registro generale dei depositi giudiziari Mod. 1 nella sola materia penale?", "correct": "Il Registro Fondo Unico Giustizia (FUG).", "wrong": ["Il registro delle notizie di reato Mod. 21.", "Il registro delle spese di giustizia prenotate a debito."]}, {"id": 120, "subject": "registry", "question": "In caso di restituzione di somme o valori sequestrati, quale comunicazione deve effettuare l'ufficio all'avente diritto ?", "correct": "Deve comunicare che, qualora non provveda al ritiro entro tre mesi dall'avviso, le somme e i valori saranno devoluti alla Cassa delle ammende.", "wrong": ["Deve comunicare che, decorso un anno senza il ritiro, le somme e i valori saranno acquisiti al patrimonio dello Stato.", "Deve comunicare che le somme e i valori saranno immediatamente versati alla Cassa delle ammende se non ritirati entro trenta giorni."]}, {"id": 121, "subject": "registry", "question": "Quale modello deve utilizzare l'ufficio per la comunicazione indirizzata sia all'avente diritto, con l'avviso previsto dall'art. 150, comma 4, del D.P.R. n. 115/2002, sia alla società Equitalia Giustizia per l'esecuzione del provvedimento di restituzione ?", "correct": "Il modello C, indirizzato sia all'avente diritto con l'avviso ex art. 150, comma 4, T.U. n. 115/2002, sia alla società Equitalia Giustizia per l'esecuzione del provvedimento.", "wrong": ["Il modello A, destinato esclusivamente alla comunicazione all'avente diritto.", "Il modello D, utilizzato per la trasmissione degli atti al concessionario della riscossione senza comunicazione all'avente diritto."]}, {"id": 122, "subject": "registry", "question": "In che modo le somme oggetto di sequestro conservativo devono essere comunicate a Equitalia Giustizia in relazione ai provvedimenti di assegnazione delle stesse ?", "correct": "Con il  modello C ter utilizzato per comunicare a Equitalia Giustizia i provvedimenti di assegnazione delle somme sequestrate.", "wrong": ["Con  il modello F23 trasmesso dall'ufficiale giudiziario.", "Con il modello 21 allegato al fascicolo dibattimentale."]}, {"id": 123, "subject": "registry", "question": "Nel Mod. 27 - Registro delle richieste di ammissione al patrocinio a spese dello Stato, vengono annotate:", "correct": "Le richieste di ammissione al patrocinio a spese dello Stato presentate nell'ambito del procedimento penale.", "wrong": ["Le liquidazioni dei compensi spettanti ai difensori delle parti ammesse al patrocinio a spese dello Stato.", "Le somme recuperate dall'Erario nei confronti dei soggetti condannati al rimborso delle spese di giustizia."]}, {"id": 124, "subject": "registry", "question": "Nel caso in cui il magistrato competente rigetti l'istanza di ammissione al patrocinio a spese dello Stato e l'interessato proponga ricorso in opposizione dinanzi al Presidente del Tribunale, come deve comportarsi la cancelleria rispetto al Mod. 27?", "correct": "L'opposizione al rigetto non dà luogo a una nuova iscrizione sul Mod. 27, poiché non si tratta di una nuova richiesta di ammissione, bensì dell'impugnazione del provvedimento negativo riguardante l'istanza originaria.", "wrong": ["La cancelleria deve obbligatoriamente aprire un nuovo numero progressivo sul Mod. 27, trattandosi di un giudizio di impugnazione autonomo che richiede l'iscrizione a un registro separato.", "La cancelleria si limita a scrivere una mera nota a margine in calce al foglio cartaceo della richiesta originaria, senza compiere alcuna annotazione sul Mod. 27 né formare un fascicolo d'ufficio, trasmettendo direttamente l'atto alla Corte di Cassazione."]}, {"id": 125, "subject": "registry", "question": "Nel sistema SIEP (Sistema Informativo dell'Esecuzione Penale), quale delle seguenti attività è normalmente gestita attraverso il relativo registro informatico?", "correct": "La gestione delle fasi dell'esecuzione penale successiva all'irrevocabilità del provvedimento, comprese le pene detentive e pecuniarie.", "wrong": ["L'iscrizione delle notizie di reato e delle indagini preliminari del Pubblico Ministero.", "La gestione del ruolo delle udienze dibattimentali e la verbalizzazione delle stesse."]}, {"id": 126, "subject": "registry", "question": "Ai sensi della disciplina sulla correzione degli errori materiali, come provvede il giudice penale e quale adempimento segue all'ordinanza che dispone la correzione?", "correct": "Il giudice provvede in camera di consiglio a norma dell'art. 127 c.p.p. e dell'ordinanza che dispone la correzione è fatta annotazione sull'originale dell'atto.", "wrong": ["Il giudice provvede con decreto fuori udienza e l'ordinanza è comunicata esclusivamente al pubblico ministero.", "Il giudice provvede con sentenza in udienza pubblica e la correzione è annotata soltanto nel fascicolo del difensore."]}, {"id": 127, "subject": "registry", "question": "Chi nomina la Commissione di sorveglianza sugli archivi per gli uffici giudiziari?", "correct": "Il Presidente della Corte di appello e il Procuratore Generale, secondo le rispettive competenze.", "wrong": ["Il Procuratore della Repubblica e il Presidente del Tribunale.", "Il Ministero della Giustizia, sentito il Consiglio Superiore della Magistratura."]}, {"id": 128, "subject": "registry", "question": "Nell'ambito della gestione documentale degli uffici giudiziari, quale organo vigila sulla corretta tenuta degli archivi correnti e di deposito, collabora alla definizione dei criteri di organizzazione, gestione e conservazione dei documenti, propone lo scarto d'archivio, cura il versamento all'Archivio di Stato e identifica gli atti di natura riservata art 41, comma 5 Dlgs 22/01/2004 42?", "correct": "La Commissione di sorveglianza sugli archivi.", "wrong": ["Il Procuratore generale presso la Corte di appello o, nelle sedi non capoluogo di distretto, il Procuratore della Repubblica.", "Il Responsabile della protezione dei dati (RPD)."]}, {"id": 129, "subject": "registry", "question": "Ai sensi del D.P.R. 18 agosto 2015, n. 133, chi presiede la Conferenza permanente?", "correct": "Il Presidente della Corte di appello ovvero, nelle sedi che non sono capoluogo del distretto, il Presidente del Tribunale.", "wrong": ["Il Procuratore generale presso la Corte di appello o, nelle sedi non capoluogo di distretto, il Procuratore della Repubblica.", "Il Dirigente amministrativo dell'ufficio giudiziario con il maggior numero di dipendenti del distretto."]}, {"id": 130, "subject": "registry", "question": "In caso di cambiamento del consegnatario,quando e come avviene il passaggio dei beni mobili ?", "correct": "Al momento del cambio del consegnatario, sulla base della materiale ricognizione dei beni risultanti dall'inventario e dalle altre scritture previste.", "wrong": ["Alla chiusura dell'esercizio finanziario, previa approvazione del conto giudiziale.", "Dopo la verifica annuale dell'inventario da parte della Commissione di sorveglianza."]}, {"id": 131, "subject": "registry", "question": "Ai sensi dell'art. 9 DPR n.254 del 4/9/2002, quale delle seguenti affermazioni è corretta in materia di incarichi di consegnatario?", "correct": "Gli incarichi di consegnatario sono conferiti, per un periodo non superiore a cinque anni, al personale inquadrato nei profili amministrativi o amministrativo-contabili in possesso della prescritta anzianità di effettivo servizio nell'area funzionale e possono essere rinnovati una sola volta.", "wrong": ["Gli incarichi di consegnatario sono conferiti senza limiti di durata e possono essere rinnovati più volte.", "Gli incarichi di consegnatario sono conferiti esclusivamente al personale dirigente e non possono essere rinnovati."]}, {"id": 132, "subject": "registry", "question": "Ai sensi dell'art. 15 del D.P.R. n. 254/2002, i consegnatari di beni mobili dello Stato sono responsabili:", "correct": "Direttamente e personalmente degli oggetti ricevuti con regolare verbale di consegna, per il periodo in cui sono stati in carica, secondo le regole generali sulla responsabilità amministrativa e contabile.", "wrong": ["Esclusivamente dei beni acquistati durante il proprio incarico, indipendentemente dalla consegna formale degli stessi.", "Soltanto in caso di dolo accertato con sentenza penale definitiva, senza alcuna responsabilità contabile."]}, {"id": 133, "subject": "registry", "question": "Ai sensi dell'art. 52 del D.P.R. 30 maggio 2002, n. 115 (Testo Unico Spese di Giustizia), in quale caso gli onorari fissi, variabili e a tempo spettanti agli ausiliari del magistrato possono essere aumentati fino al doppio?", "correct": "Quando le prestazioni sono di eccezionale importanza, complessità e difficoltà.", "wrong": ["Quando l'ausiliario svolge l'incarico in un procedimento con più di dieci parti.", "Quando il pagamento viene richiesto oltre sei mesi dalla conclusione dell'incarico."]}, {"id": 134, "subject": "registry", "question": "Ai sensi dell'art. 52 del D.P.R. 115/2002, quale conseguenza si produce quando l'ausiliario del magistrato non deposita gli elaborati entro il termine originariamente stabilito o entro quello prorogato per fatti sopravvenuti e non imputabili all'ausiliario?", "correct": "Se la prestazione non è completata nel termine originariamente stabilito o entro quello prorogato per fatti sopravvenuti e non imputabili all'ausiliario del magistrato, per gli onorari a tempo non si tiene conto del periodo successivo alla scadenza del termine e gli altri onorari sono ridotti di un terzo", "wrong": ["Tutti gli onorari spettanti all'ausiliario sono automaticamente dimezzati.", "L'ausiliario perde integralmente il diritto a qualsiasi compenso e rimborso spese."]}, {"id": 135, "subject": "registry", "question": "Quali sono le spese escluse dal novero delle spese di giustizia?", "correct": "La sepoltura dei detenuti, la traduzione dei detenuti, il trasporto, la custodia e la sepoltura delle persone decedute nella pubblica via o in luogo pubblico, il trasporto degli atti processuali e degli oggetti che servoono al processo.", "wrong": ["Esclusivamente i compensi dei difensori ammessi al patrocinio a spese dello Stato.", "Soltanto le indennità spettanti ai magistrati onorari e ai giudici popolari."]}, {"id": 136, "subject": "registry", "question": "Chi provvede all'emissione degli ordinativi di pagamento tratti sugli ordini di accreditamento ricevuti, nel rispetto dell'ordine cronologico e utilizzando le funzionalità SICOGE?", "correct": "I funzionari delegati competenti.", "wrong": ["L'Ufficio di Ragioneria Territoriale dello Stato (RTS).", "Il dirigente dell'ufficio UNEP competente per territorio."]}, {"id": 137, "subject": "registry", "question": "Chi può richiedere la visura delle iscrizioni presenti nel sistema del casellario giudiziale?", "correct": "La sola persona o ente interessato. Può essere presentata anche da persona diversa dall’interessato purché munita di specifica delega.", "wrong": ["Qualsiasi cittadino che dimostri un interesse alla consultazione.", "Il difensore dell'interessato anche senza delega o procura."]}, {"id": 138, "subject": "registry", "question": "Al termine di ogni fase processuale, cosa deve attestare il funzionario addetto nel foglio notizie prima dell'eventuale trasmissione del fascicolo in archivio?", "correct": "La presenza o l'assenza di spese da recuperare e, ricorrendone i presupposti, autorizzare la trasmissione del fascicolo in archivio.", "wrong": ["L'avvenuto pagamento di tutte le spese processuali da parte dell'imputato.", "L'avvenuta eliminazione degli atti non più necessari al procedimento."]}, {"id": 139, "subject": "registry", "question": "Ai sensi dell’art. 64-ter disp. att. c.p.p  intitolato “Diritto all’oblio degli imputati e delle persone sottoposte ad indagini la richiesta di preclusione all’indicizzazione o di deindicizzazione da chi può essere presentata?", "correct": "Dalla persona nei cui confronti sono stati pronunciati una sentenza di proscioglimento o di non luogo a procedere ovvero un provvedimento di archiviazione.", "wrong": ["Dal Pubblico Ministero d’ufficio al Giudice dell’esecuzione che ha emesso il provvedimento di condanna.", "Dalla persona nei cui confronti è stata  pronunciata una sentenza di condanna o un decreto penale con pena sospesa."]}, {"id": 140, "subject": "registry", "question": "Nell’ipotesi di richiesta di preclusione all’indicizzazione o di deindicizzazione (art. 64-ter comma 2 disp. att. c.p.p) a chi spetta provvedere?", "correct": "Alla cancelleria del giudice che ha emesso il provvedimento che appone e sottoscrive l’annotazione sul provvedimento.", "wrong": ["Al giudice che ha emesso il provvedimento che appone e sottoscrive l’annotazione sul provvedimento.", "Al giudice dell’esecuzione che, sentito il Pubblico Ministero dispone che la cancelleria  curi l’annotazione sul provvedimento."]}, {"id": 141, "subject": "registry", "question": "In caso di notifica tramite servizio postale, quando l’agente postale invia al destinatario la Comunicazione di Avvenuta Notifica (CAN – ex art. 7 della L. 890/82) ?", "correct": "la Comunicazione di Avvenuta Notifica viene inviata dall’agente postale quando consegna il plico contenente un atto giudiziario a una persona diversa dal destinatario (es. custode, familiare, ecc.).", "wrong": ["la Comunicazione di Avvenuta Notifica viene inviata dall’agente postale In caso di mancato recapito dell’atto giudiziario per assenza del destinatario", "la Comunicazione di Avvenuta Notifica viene inviata dall’agente postale in caso di mancato recapito dell’atto giudiziario per assenza o rifiuto delle persone idonee alla ricezione"]}, {"id": 142, "subject": "registry", "question": "Quando si ha per avvenuta la notifica in caso di invio al destinatario della Comunicazione di Avvenuta Notifica (CAN ex art. 7 della L. 890/82) da parte dell’agente postale?", "correct": "La Comunicazione di Avvenuta Notifica si ha per avvenuta nella data della consegna del plico contenente l’atto giudiziario.", "wrong": ["La Comunicazione di Avvenuta Notifica si ha per avvenuta nella data di consegna della CAN.", "La Comunicazione di Avvenuta Notifica si ha per avvenuta decorsi 10 giorni dal deposito e si perfeziona per “compiuta giacenza”."]}, {"id": 143, "subject": "registry", "question": "Se la persona offesa ha eletto domicilio presso il difensore, quando la notifica degli atti è perfettamente valida ed efficace?", "correct": "La notifica è perfettamente valida anche quando viene eseguita direttamente al destinatario o al suo familiare convivente.", "wrong": ["La notifica è perfettamente valida solo se viene eseguita esclusivamente presso il difensore.", "La notifica è perfettamente valida solo se  viene eseguita esclusivamente mediante deposito in cancelleria\\segreteria."]}, {"id": 144, "subject": "registry", "question": "Quando è possibile procedere alla distruzione delle denunce e degli altri documenti anonimi nonché del relativo registro mod. 46?", "correct": "Decorsi cinque anni da quando i documenti  sono pervenuti, previo provvedimento adottato annualmente dal procuratore della Repubblica con relativa verbalizzazione delle operazioni.", "wrong": ["Decorsi cinque anni da quando i documenti  sono pervenuti, previa richiesta del Pubblico Ministero al GIP di  provvedimento di autorizzazione alla distruzione e successiva verbalizzazione delle operazioni.", "Decorsi cinque anni da quando i documenti  sono pervenuti previa determinazione della Commissione di sorveglianza e scarto sugli archivi e una volta ottenuta l’autorizzazione dal Ministero della Cultura"]}, {"id": 145, "subject": "registry", "question": "In caso di richiesta di atti e documenti su supporto di memorizzazione fisica, (quali chiavette USB, CD, DVD), come è determinato il pagamento forfettario?", "correct": "E' previsto il pagamento forfettario di € 25,00 per ogni singolo supporto utilizzato, fornito dal richiedente, indipendentemente dalla sua capienza, dal numero di pagine memorizzate o dalla tipologia di dati (audio o video) riversati sul supporto stesso", "wrong": ["E' previsto il pagamento forfettario di € 8,00 per ogni singolo supporto utilizzato, fornito dall’ufficio  indipendentemente dalla sua capienza, dal numero di pagine memorizzate o dalla tipologia di dati (audio o video) riversati sul supporto stesso", "E' previsto il pagamento forfettario di € 8,00 per ogni singolo supporto utilizzato in relazione   alla sua capienza, al numero di pagine memorizzate o alla tipologia di dati (audio o video) riversati sul supporto stesso"]}, {"id": 146, "subject": "registry", "question": "La sentenza di non doversi procedere emessa ai sensi dell’art. 420 quater, primo comma c.p.p. deve  essere iscritta nel Sistema Informativo del Casellario (SIC)?", "correct": "Si, la sentenza di non doversi procedere emessa ai sensi dell’art. 420 quater, primo comma c.p.p. deve  essere iscritta nel SIC.", "wrong": ["Non essendo di condanna, la sentenza di non doversi procedere emessa ai sensi dell’art. 420 quater, primo comma c.p.p. non deve  essere iscritta nel SIC.", "No la sentenza di non doversi procedere emessa ai sensi dell’art. 420 quater, primo comma c.p.p. deve  essere iscritta nel Sistema Informativo Uffici di Sorveglianza (SIUS)."]}, {"id": 147, "subject": "registry", "question": "Nell’ipotesi di trasmissione con modalità telematica di duplicati e copie informatiche nel procedimento penale come è determinato il pagamento forfettario?", "correct": "A fronte della trasmissione, da parte della cancelleria\\segreteria, la parte deve corrispondere un diritto forfettizzato di € 8,00 per ogni trasmissione di dati, ridotto della metà per i processi dinanzi al giudice di pace", "wrong": ["A fronte della trasmissione, da parte della cancelleria\\segreteria, la parte deve corrispondere un diritto forfettizzato di € 25,00", "A fronte della trasmissione, da parte della cancelleria\\segreteria, la parte deve corrispondere un diritto forfettizzato di € 4,00 per ogni trasmissione di dati"]}, {"id": 148, "subject": "registry", "question": "Quali adempimenti cura la segreteria della Procura Generale per la domanda di grazia presentata da un condannato non detenuto né internato?", "correct": "Cura la ricezione e la protocollazione della domanda, l’acquisizione delle informazioni disposte dal Procuratore Generale, la formazione del fascicolo e la trasmissione al Ministro della giustizia con le osservazioni del Procuratore Generale, ai sensi dell’art. 681, comma 2, c.p.p.", "wrong": ["Trasmette direttamente la domanda al Presidente della Repubblica con parere vincolante del Procuratore Generale.", "Predispone una decisione provvisoria di concessione della grazia da sottoporre al Procuratore Generale."]}, {"id": 149, "subject": "registry", "question": "Le iscrizioni ex art. 335 c.p.p. sono sempre comunicabili ai soggetti legittimati che ne facciano richiesta?", "correct": "No. Sono escluse per i delitti indicati dall’art. 407, comma 2, lett. a), c.p.p.; inoltre il PM può segretarle con decreto motivato, per specifiche esigenze investigative, fino a tre mesi non rinnovabili.", "wrong": ["Sì, salvo che il pubblico ministero ritenga genericamente inopportuna la comunicazione.", "No, perché durante le indagini le iscrizioni non sono mai comunicabili."]}, {"id": 150, "subject": "registry", "question": "L’interessato deve motivare la richiesta del proprio certificato del casellario giudiziale?", "correct": "No. L’art. 24, comma 1, D.P.R. 313/2002 riconosce il diritto di ottenere il certificato senza motivare la richiesta.", "wrong": ["No, ma soltanto se non risultano condanne definitive.", "Sì, deve sempre dimostrare uno specifico interesse giuridico."]}, {"id": 151, "subject": "administrative", "question": "Qual è la funzione principale del Responsabile Unico del Progetto (RUP) nell'ambito di una procedura di affidamento?", "correct": "Assicurare il coordinamento e il corretto svolgimento delle fasi di programmazione, progettazione, affidamento ed esecuzione dell'intervento, esercitando i compiti attribuitigli dall'Allegato I.2 .", "wrong": ["Verificare esclusivamente la regolarità contabile degli atti di gara e autorizzare i pagamenti all'appaltatore esercitando i compiti attribuitigli  dall'Allegato I.11.", "Sostituire la commissione giudicatrice nella valutazione delle offerte tecniche ed economiche, esercitando i compiti attribuitigli dall'Allegato II.17 ."]}, {"id": 152, "subject": "administrative", "question": "Ai sensi del D.Lgs. 36/2023, come sono svolte le attività e i procedimenti amministrativi connessi al ciclo di vita dei contratti pubblici?", "correct": "Sono svolti digitalmente mediante piattaforme e servizi digitali previsti dal Codice.", "wrong": ["Possono essere svolti in forma digitale o cartacea a scelta della stazione appaltante.", "Sono svolti digitalmente solo per gli affidamenti sopra le soglie europee."]}, {"id": 153, "subject": "administrative", "question": "Ai sensi del D.Lgs. 36/2023, in che forma deve essere stipulato il contratto?", "correct": "Deve essere sempre  stipulato, a pena di nullità, in forma scritta,  in forma pubblica amministrativa a cura dell’ufficiale rogante della stazione appaltante, ovvero con atto pubblico notarile informatico oppure mediante scrittura privata.", "wrong": ["Deve essere stipultato sempre in forma scritta esclusivamente  per i contratti di importo superiore alle soglie europee , a pena di annullbilità.", "E'  stipulato solo a discrezione della stazione appaltante senza che sussita l'obbligo di specifiche modalità formalità."]}, {"id": 154, "subject": "administrative", "question": "Ai sensi del D.Lgs. 36/2023, a che cosa serve il Fascicolo Virtuale dell'Operatore Economico (FVOE)?", "correct": "Verificare l'assenza delle cause di esclusione e il possesso dei requisiti richiesti per la partecipazione alle procedure di affidamento.", "wrong": ["Attribuire automaticamente il punteggio dell'offerta tecnica presentata dall'operatore economico.", "Sostituire integralmente la valutazione della commissione giudicatrice o del RUP."]}, {"id": 155, "subject": "administrative", "question": "Ai sensi del D.Lgs. 36/2023, le clausole di revisione dei prezzi nei documenti di gara iniziali sono:", "correct": "Obbligatorie per le prestazioni oggetto del contratto.", "wrong": ["Facoltative in quanto  rimesse alla discrezionalità della stazione appaltante.", "Ammesse esclusivamente per gli appalti di lavori, senza obbligo di inserimento nei documenti di gara."]}, {"id": 156, "subject": "administrative", "question": "In presenza di una offerta che appare anormalmente bassa che cosa è consentito alla stanzione appaltante?", "correct": "Richiedere per iscritto all'operatore economico le spiegazioni sul prezzo o sui costi proposti, assegnando a tal fine un termine non superiore a quindici giorni.", "wrong": ["Verificare d'ufficio presso altre amministrazioni se  il ribasso offerto sia compatibile con l'organizzazione aziendale e con i costi dichiarati dall'operatore economico.", "Accertared'ufficio  esclusivamente il rispetto dei minimi salariali e dei costi della sicurezza entro un  termine non superiore a trenta giorni."]}, {"id": 157, "subject": "administrative", "question": "Nel sistema delle qualificazioni  previsto dal D.Lgs. 36/2023, cosa può fare una stazione appaltante qualificata?", "correct": "Effettuare procedure di affidamento di lavori, servizi e forniture secondo i livelli previsti dal Codice.", "wrong": ["Affidare contratti di qualsiasi importo senza alcuna limitazione.", "Iscrivere gli operatori economici alla Banca dati nazionale dei contratti pubblici."]}, {"id": 158, "subject": "administrative", "question": "Ai sensi del D.Lgs. 36/2023, quando la stazione appaltante può disporre la risoluzione del contratto?", "correct": "Quando ricorrono gravi inadempimenti dell'appaltatore tali da compromettere la corretta esecuzione delle prestazioni contrattuali.", "wrong": ["Quando l'operatore economico chiede un adeguamento dei prezzi previsto dal contratto.", "Quando l'esecuzione delle prestazioni procede regolarmente ma con costi inferiori a quelli stimati e oggetto del contratto."]}, {"id": 159, "subject": "administrative", "question": "In che cosa si sostanzia il principio di rotazione?", "correct": "Nel divieto  dell’affidamento o dell’aggiudicazione al contraente uscente nei casi in cui due consecutivi affidamenti abbiano a oggetto una commessa rientrante nello stesso settore merceologico, oppure nella stessa categoria di opere, oppure nello stesso settore merceologico.", "wrong": ["Nel divieto di invito alla procedura di gara e di   aggiudicazione al contraente uscente nel caso in cui quattro consecutivi affidamenti abbiano a oggetto la stessa categoria di opere.", "Nel divieto  di invito alla procedura di gara e all’affidamento al contraente uscente nel caso in cui tre consecutivi affidamenti abbiano a oggetto una commessa nello stesso settore merceologico."]}, {"id": 160, "subject": "administrative", "question": "Nell'ambito dei contratti pubblici, si può derogare al principio di rotazione?", "correct": "Si può derogare a determinate condizioni debitamente motivate con riferimento alla struttura del mercato, alla effettiva assenza di alternative, nonché di accurata esecuzione del precedente contratto Tali condizioni debbono essere  concorrenti e non alternative.", "wrong": ["Non è mai possibile derogare al principio di rotazione.", "E' sempre  possibile derogare senza limitazioni e senza obbligo di motivazione."]}, {"id": 161, "subject": "administrative", "question": "Quando è possibile ricorrere all'affidamento diretto?", "correct": "E' possibile negli affidamenti al di sotto di determinati importi,  anche senza consultazione di più operatori economici, assicurando che siano in possesso di documentate esperienze pregresse idonee all’esecuzione delle prestazioni contrattuali.", "wrong": ["E' possibile  solo negli affidamenti al di sopra di determinati importi,  anche senza consultazione di più operatori economici.", "E' sempre obbligatorio nelle concessioni e  negli affidamenti al di sopra di determinati importi ."]}, {"id": 162, "subject": "administrative", "question": "Cosa si regola nel patto di integrità o protocollo di legalità ?", "correct": "I comportamenti e le reciproche e formali obbligazioni tra l’Amministrazione e gli Operatori Economici che prendono parte alle procedure di affidamento e gestione degli appalti di lavori, servizi e forniture, nonché del personale appartenente all’Amministrazione e si applica a tutte le procedure di gara, compresi gli affidamenti diretti", "wrong": ["I comportamenti e  le reciproche e formali obbligazioni tra l’Amministrazione e gli Operatori Economici nel caso di affidamento e gestione di appalto di lavori e si  applica alle sole procedure di gara sopra soglia comunitaria, con  esclusione  degli affidamenti diretti", "I comportamenti e le reciproche e formali obbligazioni tra  gli Operatori Economici e si  applica alle sole procedure di gara sotto soglia comunitaria, con esclusione degli affidamenti diretti"]}, {"id": 163, "subject": "administrative", "question": "Il codice dei contratti prevede dei limiti percentuali quantitativi  per  il subappalto?", "correct": "Nel codice sono stati eliminati i limiti percentuali al subappalto. Qualsiasi accordo che affidi a terzi l’intera esecuzione delle prestazioni o la prevalente esecuzione delle lavorazioni relative alla categoria prevalente e dei contratti ad alta intensità di manodopera è nullo.", "wrong": ["Il codice prevede una percentuale massima del subappalto fissata al 30% del valore del contratto. E' consentito l'accordo con il quale si affida a terzi l’intera esecuzione delle prestazioni o la prevalente esecuzione delle lavorazioni relative alla categoria prevalente e dei contratti ad alta intensità di manodopera.", "Nel codice sono stati eliminati i limiti percentuali al subappalto e sono consentiti gli accordi con i quali si affda a terzi l’intera esecuzione delle prestazioni o la prevalente esecuzione delle lavorazioni relative alla categoria prevalente e dei contratti ad alta intensità di manodopera."]}, {"id": 164, "subject": "administrative", "question": "In caso di contrasto o contraddittorietà tra le disposizioni contenute nei documenti di gara e quelle inserite nel bando o nell'avviso di gara, quali prevalgono?", "correct": "Prevalgono quelle inserite nel bando o nell'avviso di gara.", "wrong": ["Prevalgono quelle inserite nel capitolato speciale.", "Prevalgono quelle contenute nel disciplinare  di gara."]}, {"id": 165, "subject": "administrative", "question": "Ai sensi del D.lgs. 33/2013, quale finalità persegue principalmente la trasparenza amministrativa?", "correct": "Favorire il controllo diffuso sul perseguimento delle funzioni istituzionali e sull'utilizzo delle risorse pubbliche, promuovendo la partecipazione e tutelando i diritti nei limiti previsti dalla legge.", "wrong": ["Garantire che tutti i documenti amministrativi siano  pubblicati  online  senza alcuna limitazione.", "Favorire e consentire esclusivamente alle altre pubbliche amministrazioni e ai dipendenti pubblici di conoscere gli atti interni dell'amministrazione."]}, {"id": 166, "subject": "administrative", "question": "Quale rimedio è previso nel caso in cui  una pubblica amministrazione omette di pubblicare un documento, un'informazione o un dato per cui sussiste un obbligo di pubblicazione?", "correct": "Chiunque può presentare una richiesta di accesso civico semplice affinché l'amministrazione provveda alla pubblicazione dovuta.", "wrong": ["Si può richiedere l'accesso soltanto se si dimostra di essere titolare di un interesse diretto, concreto e attuale relativo al documento.", "Si può ottenere automaticamente il risarcimento del danno e la rimozione del responsabile dell'omessa pubblicazione."]}, {"id": 167, "subject": "administrative", "question": "Quale caratteristica distingue l'accesso civico generalizzato dall'accesso documentale previsto dalla legge 241/1990?", "correct": "L'accesso civico generalizzato può essere richiesto da chiunque, senza necessità di motivare la domanda, nei limiti posti a tutela degli interessi pubblici e privati dall'art. 5-bis del D.lgs. 33/2013.", "wrong": ["L'accesso civico generalizzato è riservato esclusivamente a chi partecipa al procedimento e dimostri un interesse diretto, concreto e attuale collegato ai documenti richiesti.", "L'accesso civico  generalizzato consente di ottenere qualsiasi informazione, anche non detenuta dall'amministrazione, senza limiti relativi alla riservatezza."]}, {"id": 168, "subject": "administrative", "question": "Secondo la legge 241/1990, quale requisito deve possedere il soggetto che richiede l'accesso documentale?", "correct": "Deve essere titolare di un interesse diretto, concreto e attuale, corrispondente a una situazione giuridicamente tutelata e collegata al documento richiesto.", "wrong": ["Deve dimostrare un interesse generico a conoscere il funzionamento dell'amministrazione, senza ulteriori requisiti.", "Deve  essere necessariamente rivestire la qualifica di dipendente pubblico o un rappresentante di un ente pubblico e non di semplice cittadino."]}, {"id": 169, "subject": "administrative", "question": "Quale funzione caratterizza il Responsabile della prevenzione della corruzione e della trasparenza (RPCT)?", "correct": "Predisporre o curare, secondo le competenze attribuitegli, le misure di prevenzione della corruzione e vigilare sull'attuazione degli obblighi di trasparenza, segnalando le criticità agli organi competenti.", "wrong": ["Irrogare direttamente qualsiasi sanzione penale o disciplinare nei confronti dei dipendenti che violano gli obblighi di trasparenza.", "Sostituire ordinariamente tutti i dirigenti nell'adozione degli atti amministrativi e nella gestione del personale."]}, {"id": 170, "subject": "administrative", "question": "9. Ai sensi del D.lgs. 165/2001, come sono ripartite le competenze per l’irrogazione delle sanzioni disciplinari?", "correct": "Il responsabile della struttura presso cui il dipendente presta servizio è competente per il rimprovero verbale, mentre per le infrazioni punibili con una sanzione superiore è competente l’Ufficio per i procedimenti disciplinari.", "wrong": ["Il responsabile della struttura è competente per tutte le sanzioni disciplinari, mentre l’Ufficio per i procedimenti disciplinari interviene esclusivamente in caso di impugnazione.", "Il rimprovero verbale è di competenza esclusiva dell’Ufficio per i procedimenti disciplinari, mentre le sanzioni superiori sono irrogate dal giudice ordinario."]}, {"id": 171, "subject": "administrative", "question": "Quale obbligo grava sul dipendente pubblico in relazione al codice di comportamento?", "correct": "Osservare i doveri di diligenza, lealtà, imparzialità e buona condotta previsti dalla legge e dal codice applicabile, tenendo conto anche delle regole sul conflitto di interessi.", "wrong": ["Rispettare il codice esclusivamente quando abbia ricevuto una disposizione scritta del proprio dirigente relativa al singolo comportamento.", "Osservare il codice soltanto durante l'orario di lavoro, senza che rilevino eventuali condotte extralavorative."]}, {"id": 172, "subject": "administrative", "question": "Quando si configura  la responsabilità amministrativo-contabile per un dipendente pubblico?", "correct": "Quando il danno è  riconducibile alla condotta del dipendente e ricorrono gli ulteriori presupposti previsti dalla legge, tra cui il dolo o la colpa grave.", "wrong": ["Quando si è in presenza di qualsiasi tipo di  errore formale senza stretta correlazione con la condotta e anche in assenza di danno", "Si configura soltanto quando il dipendente provoca un danno a un cittadino senza che rilevi la sua condotta."]}, {"id": 173, "subject": "administrative", "question": "Qual è il termine ordinario previsto dal D.lgs. 33/2013 per concludere il procedimento relativo a una richiesta di accesso civico generalizzato?", "correct": "Trenta giorni dalla presentazione della richiesta, salve le sospensioni e le altre disposizioni previste dalla legge.", "wrong": ["Quindici giorni dalla presentazione della richiesta, salve le sospensioni e le altre disposizioni previste dalla legge.", "Novanta giorni dalla presentazione della richiesta, prorogabili liberamente dall'amministrazione  in relazione al carico di lavoro."]}, {"id": 174, "subject": "administrative", "question": "In quali casi  l'amministrazione può differire l'accesso ai documenti amministrativi?", "correct": "Quando il differimento è necessario per salvaguardare esigenze previste dalla legge, ad esempio per evitare un pregiudizio al regolare svolgimento dell'azione amministrativa, nei casi e nei limiti consentiti.", "wrong": ["Ogni volta che l'ufficio ritenga opportuno ridurre il numero delle richieste, senza dover indicare alcuna ragione.", "Soltanto quando il richiedente non è cittadino italiano, indipendentemente dall'interesse fatto valere."]}, {"id": 175, "subject": "administrative", "question": "Se un atto da pubblicare contiene dati personali non necessari rispetto alla divulgazione, come deve procedere  la pubblica amministrazione?", "correct": "Deve pubblicare le informazioni richieste dalla legge e oscurare, quando necessario, i dati non pertinenti o non divulgabili.", "wrong": ["Non può mai pubblicare un documento che contiene dati personali, posto che l'oscuramento degli stessi configura una modifica del documento originario e come tale vietata.", "Deve pubblicare sempre il documento completo, senza oscurare alcun dato."]}, {"id": 176, "subject": "administrative", "question": "In ambito disciplinare, quale conseguenza può derivare dalla falsa attestazione della presenza in servizio realizzata con modalità fraudolente?", "correct": "Può trovare applicazione il licenziamento disciplinare, ferme le ulteriori responsabilità previste dall'ordinamento e le garanzie procedimentali applicabili.", "wrong": ["Può essere applicato esclusivamente un richiamo informale e generico, senza possibilità di sanzioni più gravi, in quanto reato.", "Il comportamento è irrilevante sul piano disciplinare se il dipendente recupera successivamente le ore di assenza."]}, {"id": 177, "subject": "administrative", "question": "Se un dipendente pubblico, svolgendo le proprie funzioni, provoca un danno ingiusto a un terzo, chi può essere responsabile?", "correct": "Il dipendente può essere direttamente responsabile, secondo la legge, per gli atti compiuti in violazione dei diritti e la responsabilità civile può estendersi anche all'amministrazione.", "wrong": ["Soltanto l'amministrazione, perché il dipendente non risponde mai personalmente dei propri atti.", "Soltanto il dipendente, perché l'amministrazione non può mai essere responsabile."]}, {"id": 178, "subject": "administrative", "question": "Come può un dipendente segnalare una violazione che rientra nel campo di applicazione del whistleblowing?", "correct": "Utilizzando i canali previsti dalla legge.Può ricorrere alla segnalazione esterna o alla divulgazione pubblica soltanto alle condizioni stabilite dalla normativa.", "wrong": ["Può  esclusivamente effettuare la segnalazione al proprio superiore gerarchico, con divieto di utilizzare altri canali.", "Pubblicando obbligatoriamente sui social network tutte le informazioni di cui è venuto a conoscenza."]}, {"id": 179, "subject": "administrative", "question": "Quando il silenzio della pubblica amministrazione può valere come accoglimento di una domanda?", "correct": "Quando la legge prevede il silenzio-assenso e decorre il termine senza che l'amministrazione emetta un provvedimento formale.", "wrong": ["Sempre non essendo previste eccezioni e per qualsiasi tipologia di domanda presentata alla pubblica amministrazione.", "Nei soli  procedimenti avviati d'ufficio direttamente dall'amministrazione e con effetto di rigetto."]}, {"id": 180, "subject": "administrative", "question": "Ai sensi dell'art. 21-septies della legge 241/1990, in quali casi il provvedimento amministrativo è  nullo?", "correct": "In assenza degli elementi essenziali, in presenza del difetto assoluto di attribuzione, di violazione o elusione del giudicato e negli altri casi espressamente previsti dalla legge.", "wrong": ["Solo in presenza di  qualsiasi tipologia di imprecisione formale contenuta nel provvedimento, anche quando sia del tutto irrilevante.", "Per ogni violazione di una norma procedimentale, senza che distinzione tra nullità e annullabilità, non prevedendo la normala  tassatività."]}]);
